static volatile sig_atomic_t Got_signal = 0;







static volatile sig_atomic_t Status_printed = 0;







static void emit_status(const char *fmt, ...) {
  if (Status_printed) return;
  Status_printed = 1;
  va_list ap;
  va_start(ap, fmt);
  vprintf(fmt, ap);
  va_end(ap);
  fflush(stdout);
}











static int emit_failed(const char *fmt, ...) {
  if (Status_printed) return 1;
  va_list ap;
  char msg[2048];
  va_start(ap, fmt);
  vsnprintf(msg, sizeof(msg), fmt, ap);
  va_end(ap);
  fprintf(stderr, "%% ========== Verification Report ==========\n");
  fprintf(stderr, "%% Structural flaw: %s\n", msg);
  Status_printed = 1;
  printf("%% SZS status VerifiedBad : %s\n", msg);
  fflush(stdout);
  return 1;
}







static int emit_notverified(const char *fmt, ...) {
  if (Status_printed) return 1;
  va_list ap;
  char msg[2048];
  va_start(ap, fmt);
  vsnprintf(msg, sizeof(msg), fmt, ap);
  va_end(ap);
  fprintf(stderr, "%% ========== Verification Report ==========\n");
  fprintf(stderr, "%% Uncertain: %s\n", msg);
  Status_printed = 1;
  printf("%% SZS status Unknown : %s\n", msg);
  fflush(stdout);
  return 1;
}






























static double Suspicious_score = 0.0;
static const double Suspicious_threshold = 2.0;  
static std::vector<std::string> Suspicious_reasons;






static int Skolem_undecided_count = 0;
static std::vector<std::string> Skolem_undecided_names;











static int Arith_undecided_count = 0;
static std::vector<std::string> Arith_undecided_names;










static bool Hedge_occurred = false;
static std::vector<std::string> Hedge_reasons;






static bool Fail_fast_mode = false;

static void reset_suspicion(void) {
  Suspicious_score = 0.0;
  Suspicious_reasons.clear();
  Skolem_undecided_count = 0;
  Skolem_undecided_names.clear();
  Arith_undecided_count = 0;
  Arith_undecided_names.clear();
  Hedge_occurred = false;
  Hedge_reasons.clear();
}






static std::string join_names_capped(const std::vector<std::string> &names,
                                      size_t cap = 10) {
  std::string out;
  size_t shown = names.size() < cap ? names.size() : cap;
  for (size_t i = 0; i < shown; i++) {
    if (i) out += ", ";
    out += names[i];
  }
  if (names.size() > shown) {
    char more[32];
    snprintf(more, sizeof(more), ", +%zu more", names.size() - shown);
    out += more;
  }
  return out;
}





static void mark_suspicious_weighted(double weight, const char *fmt, ...) {
  va_list ap;
  char msg[1024];
  va_start(ap, fmt);
  vsnprintf(msg, sizeof(msg), fmt, ap);
  va_end(ap);
  if (weight < 0.0) weight = 0.0;
  if (weight > 1.0) weight = 1.0;
  Suspicious_score += weight;
  char tag[64];
  snprintf(tag, sizeof(tag), "+%.2f→%.2f", weight, Suspicious_score);
  Suspicious_reasons.push_back(std::string(tag) + " " + msg);
  fprintf(stderr, "  SUSPICIOUS [%s]: %s\n", tag, msg);
}

static void mark_suspicious(const char *fmt, ...) {
  va_list ap;
  char msg[1024];
  va_start(ap, fmt);
  vsnprintf(msg, sizeof(msg), fmt, ap);
  va_end(ap);
  mark_suspicious_weighted(1.0, "%s", msg);
}









static bool mark_hedge(const char *fmt, ...) {
  va_list ap;
  char msg[1024];
  va_start(ap, fmt);
  vsnprintf(msg, sizeof(msg), fmt, ap);
  va_end(ap);
  Hedge_occurred = true;
  Hedge_reasons.push_back(msg);
  fprintf(stderr, "  HEDGE: %s\n", msg);
  if (Fail_fast_mode) {
    emit_status("%% SZS status Unknown : %s\n", msg);
    return true;
  }
  return false;
}





static int finalize_suspicion_verdict(double wall_sec) {
  fprintf(stderr, "%% ========== Verification Report ==========\n");
  fprintf(stderr, "%% Wall clock: %.3fs\n", wall_sec);
  if (!Suspicious_reasons.empty()) {
    fprintf(stderr, "%% Suspicious score: %.2f (%zu finding(s))\n",
            Suspicious_score, Suspicious_reasons.size());
    for (size_t i = 0; i < Suspicious_reasons.size(); i++)
      fprintf(stderr, "%%   - %s\n", Suspicious_reasons[i].c_str());
  }
  if (Suspicious_score >= Suspicious_threshold) {
    fprintf(stderr,
            "%% suspicious score %.2f ≥ threshold %.2f — escalating to FailedVerified\n",
            Suspicious_score, Suspicious_threshold);
    emit_status(
        "%% SZS status VerifiedBad : suspicious score %.2f >= threshold %.2f\n",
        Suspicious_score, Suspicious_threshold);
    return 1;
  }
  





  std::vector<std::string> reasons;
  if (Skolem_undecided_count > 0) {
    char buf[256];
    snprintf(buf, sizeof(buf),
             "%d skolemize step(s) too large to verify structurally: %s",
             Skolem_undecided_count,
             join_names_capped(Skolem_undecided_names).c_str());
    reasons.push_back(buf);
  }
  if (Arith_undecided_count > 0) {
    char buf[256];
    snprintf(buf, sizeof(buf),
             "%d arith_evaluation/arith_conflict step(s) could not be "
             "verified structurally: %s", Arith_undecided_count,
             join_names_capped(Arith_undecided_names).c_str());
    reasons.push_back(buf);
  }
  if (Suspicious_score > 0.0) {
    char buf[64];
    snprintf(buf, sizeof(buf), "suspicious score %.2f < threshold %.2f",
             Suspicious_score, Suspicious_threshold);
    reasons.push_back(buf);
  }
  for (size_t i = 0; i < Hedge_reasons.size(); i++)
    reasons.push_back(Hedge_reasons[i]);
  if (!reasons.empty()) {
    fprintf(stderr, "%% hedging to NotVerified (%zu reason(s))\n",
            reasons.size());
    emit_status("%% SZS status Unknown : %s\n",
                join_names_capped(reasons, 6).c_str());
    return 1;
  }
  emit_status("%% SZS status VerifiedGood\n");
  return 0;
}
static int Audit_sidestep = 0;  




static int Sidestep_audit = 0;
static std::string Sidestep_audit_path;
static FILE *Sidestep_audit_fp = NULL;












static const char *Current_proof_name = "?";  

struct AuditTally {
  int accept_thm;     
  int accept_nonthm;  
  int accept_unk;     
  int reject_thm;     
  int reject_nonthm;  
  int reject_unk;     
  int abstain_thm;    
  int abstain_nonthm; 
  int abstain_unk;    
  int noatp;          
  AuditTally() : accept_thm(0), accept_nonthm(0), accept_unk(0),
                 reject_thm(0), reject_nonthm(0), reject_unk(0),
                 abstain_thm(0), abstain_nonthm(0), abstain_unk(0),
                 noatp(0) {}
};
static AuditTally Audit_tally;

static void sidestep_audit_dump_summary(void) {
  if (!Sidestep_audit) return;
  const AuditTally &t = Audit_tally;
  int total = t.accept_thm + t.accept_nonthm + t.accept_unk
            + t.reject_thm + t.reject_nonthm + t.reject_unk
            + t.abstain_thm + t.abstain_nonthm + t.abstain_unk
            + t.noatp;
  if (total == 0) return;
  fprintf(stderr,
    "%% ========== SideStep Audit Summary (this proof) ==========\n"
    "%%                  ATP=theorem  ATP=non-thm  ATP=unknown\n"
    "%% ss=accept       %10d %12d %12d\n"
    "%% ss=reject       %10d %12d %12d\n"
    "%% ss=abstain      %10d %12d %12d\n"
    "%% ss=any  noatp   %10d\n"
    "%% Total audited:  %d\n",
    t.accept_thm,  t.accept_nonthm,  t.accept_unk,
    t.reject_thm,  t.reject_nonthm,  t.reject_unk,
    t.abstain_thm, t.abstain_nonthm, t.abstain_unk,
    t.noatp, total);
  if (t.accept_nonthm > 0) {
    fprintf(stderr, "%% *** %d SOUNDNESS VIOLATION(S): SideStep accepted, ATP refuted\n",
            t.accept_nonthm);
  }
  if (t.reject_thm > 0) {
    fprintf(stderr, "%% *** %d FALSE-REJECT(S): SideStep rejected, ATP proved\n",
            t.reject_thm);
  }
  if (t.abstain_thm > 0) {
    fprintf(stderr, "%% %d coverage gap(s): SideStep abstained, ATP proved\n",
            t.abstain_thm);
  }
  if (Sidestep_audit_fp) { fclose(Sidestep_audit_fp); Sidestep_audit_fp = NULL; }
}






#define MAX_WORKERS 64
static volatile pid_t Worker_pids[MAX_WORKERS];




static volatile pid_t Sync_pid = 0;

static void worker_add(pid_t pid) {
  for (int i = 0; i < MAX_WORKERS; i++) {
    if (Worker_pids[i] == 0) {
      Worker_pids[i] = pid;
      return;
    }
  }
}

static void worker_remove(pid_t pid) {
  for (int i = 0; i < MAX_WORKERS; i++) {
    if (Worker_pids[i] == pid) {
      Worker_pids[i] = 0;  
      return;
    }
  }
}

__attribute__((cold))
static void deadline_handler(int sig) {
  (void)sig;
  Got_signal = 1;
  










  if (!Status_printed) {
    Status_printed = 1;
    if (Suspicious_score >= Suspicious_threshold) {
      
      const char msg[] =
        "% SZS status VerifiedBad : suspicion accumulator past "
        "threshold at interruption\n";
      write(STDOUT_FILENO, msg, sizeof(msg) - 1);
    } else if (sig == SIGALRM || sig == SIGXCPU || sig == SIGTERM) {
      
      const char msg[] = "% SZS status Timeout\n";
      write(STDOUT_FILENO, msg, sizeof(msg) - 1);
    } else {
      
      const char msg[] = "% SZS status Unknown\n";
      write(STDOUT_FILENO, msg, sizeof(msg) - 1);
    }
  }
  
  if (Sync_pid > 0)
    killpg(Sync_pid, SIGKILL);
  
  for (int i = 0; i < MAX_WORKERS; i++)
    if (Worker_pids[i] > 0)
      killpg(Worker_pids[i], SIGKILL);
  _exit(1);
}

static void install_signal_handlers(void) {
  struct sigaction sa;
  memset(&sa, 0, sizeof(sa));
  sa.sa_handler = deadline_handler;
  sa.sa_flags = 0;
  sigaction(SIGTERM, &sa, NULL);
  sigaction(SIGXCPU, &sa, NULL);
  sigaction(SIGALRM, &sa, NULL);
  sigaction(SIGINT,  &sa, NULL);
  



  sigaction(SIGSEGV, &sa, NULL);
  sigaction(SIGBUS,  &sa, NULL);
  sigaction(SIGABRT, &sa, NULL);
  sigaction(SIGFPE,  &sa, NULL);
  sigaction(SIGILL,  &sa, NULL);
}




