static inline void ltrim(std::string &s) {
  size_t i = 0;
  while (i < s.size() && (s[i]==' '||s[i]=='\n'||s[i]=='\r'||s[i]=='\t')) i++;
  if (i > 0) s.erase(0, i);
}

static inline void rtrim(std::string &s) {
  while (!s.empty() && (s.back()==' '||s.back()=='\n'||s.back()=='\r'||s.back()=='\t'))
    s.pop_back();
}

static inline void strim(std::string &s) { ltrim(s); rtrim(s); }






static inline size_t skip_quoted_span(const std::string &s, size_t j) {
  char q = s[j];
  j++;
  while (j < s.size() && s[j] != q) {
    if (q == '\'' && s[j] == '\\' && j + 1 < s.size()) j++;
    j++;
  }
  return j;  
}



static size_t find_arg_comma(const std::string &s, size_t from) {
  int depth = 0;
  for (size_t j = from; j < s.size(); j++) {
    char c = s[j];
    if (c == '\'' || c == '"') { j = skip_quoted_span(s, j); continue; }
    if (c == '(' || c == '[') depth++;
    else if (c == ')' || c == ']') depth--;
    else if (c == ',' && depth == 0) return j;
  }
  return std::string::npos;
}




static const char *Known_provers[] = { "eprover", "prover9", "vampire", NULL };
static AtpType Known_types[]       = { ATP_EPROVER, ATP_PROVER9, ATP_VAMPIRE };



static std::string Exe_dir;


static bool is_executable_file(const char *path) {
  struct stat st;
  if (stat(path, &st) != 0) return false;
  return S_ISREG(st.st_mode) && access(path, X_OK) == 0;
}



static std::string find_executable(const std::string &cmd) {
  if (cmd.find('/') != std::string::npos)
    return is_executable_file(cmd.c_str()) ? cmd : "";
  
  std::string local = "./" + cmd;
  if (is_executable_file(local.c_str())) return local;
  
  const char *path = getenv("PATH");
  if (path) {
    std::string pathstr(path);
    size_t start = 0;
    while (start < pathstr.size()) {
      size_t colon = pathstr.find(':', start);
      if (colon == std::string::npos) colon = pathstr.size();
      std::string full = pathstr.substr(start, colon - start) + "/" + cmd;
      if (is_executable_file(full.c_str())) return full;
      start = colon + 1;
    }
  }
  return "";
}



static bool auto_discover_atp(void) {
  
  if (!Exe_dir.empty()) {
    std::string co = Exe_dir + "/eprover";
    if (is_executable_file(co.c_str())) {
      Atp_command = co;
      Atp_type = ATP_EPROVER;
      return true;
    }
  }
  
  std::string local = "./eprover";
  if (is_executable_file(local.c_str())) {
    Atp_command = local;
    Atp_type = ATP_EPROVER;
    return true;
  }
  
  const char *path = getenv("PATH");
  if (path) {
    std::string pathstr(path);
    size_t start = 0;
    while (start < pathstr.size()) {
      size_t colon = pathstr.find(':', start);
      if (colon == std::string::npos) colon = pathstr.size();
      std::string full = pathstr.substr(start, colon - start) + "/eprover";
      if (access(full.c_str(), X_OK) == 0) {
        Atp_command = full;
        Atp_type = ATP_EPROVER;
        return true;
      }
      start = colon + 1;
    }
  }
  return false;
}





static bool resolve_atp(const std::string &cmd) {
  std::string found = find_executable(cmd);
  if (!found.empty()) {
    Atp_command = found;
    return true;
  }
  
  Atp_command = cmd;
  return false;
}



