struct CnfJob {
  std::string source_name;
  pid_t pid;
  int out_fd;  
};






static CnfJob start_cnf_async(const std::string &problem,
                               const std::string &cmd, int atp_kind,
                               int timeout_sec) {
  CnfJob job;
  job.source_name.clear();
  job.pid = -1;
  job.out_fd = -1;

  int in_pipe[2], out_pipe[2];
  if (pipe(in_pipe) < 0) return job;
  if (pipe(out_pipe) < 0) { close(in_pipe[0]); close(in_pipe[1]); return job; }

  pid_t pid = fork();
  if (pid < 0) {
    close(in_pipe[0]); close(in_pipe[1]);
    close(out_pipe[0]); close(out_pipe[1]);
    return job;
  }
  if (pid == 0) {
    setpgid(0, 0);
    dup2(in_pipe[0], STDIN_FILENO);
    close(in_pipe[0]); close(in_pipe[1]);
    dup2(out_pipe[1], STDOUT_FILENO);
    close(out_pipe[0]); close(out_pipe[1]);
    int nfd = open("/dev/null", O_WRONLY);
    if (nfd >= 0) { dup2(nfd, STDERR_FILENO); close(nfd); }
    if (atp_kind == 1) {  
      char t[32];
      snprintf(t, sizeof(t), "%d", timeout_sec);
      execl(cmd.c_str(), cmd.c_str(), "-cnf", "-t", t, (char *)NULL);
    } else if (atp_kind == 2) {  
      char t[32];
      snprintf(t, sizeof(t), "%d", timeout_sec);
      execl(cmd.c_str(), cmd.c_str(),
            "--mode", "clausify", "-t", t, (char *)NULL);
    } else {  
      char t[48];
      snprintf(t, sizeof(t), "--cpu-limit=%d", timeout_sec);
      execl(cmd.c_str(), cmd.c_str(),
            "--cnf", "--no-preprocessing", "--definitional-cnf=0",
            t, "--", (char *)NULL);
    }
    _exit(1);
  }
  
  close(in_pipe[0]);
  close(out_pipe[1]);
  setpgid(pid, pid);
  size_t pos = 0;
  while (pos < problem.size()) {
    ssize_t w = write(in_pipe[1], problem.data() + pos, problem.size() - pos);
    if (w <= 0) break;
    pos += (size_t)w;
  }
  if (pos > 0 && problem[pos-1] != '\n') write(in_pipe[1], "\n", 1);
  close(in_pipe[1]);

  job.pid = pid;
  job.out_fd = out_pipe[0];
  return job;
}



static std::vector<std::string> collect_cnf_result(CnfJob &job) {
  std::vector<std::string> clauses;
  if (job.pid <= 0 || job.out_fd < 0) return clauses;

  std::string output;
  char buf[4096];
  ssize_t r;
  while ((r = read(job.out_fd, buf, sizeof(buf))) > 0)
    output.append(buf, (size_t)r);
  close(job.out_fd);
  job.out_fd = -1;

  int status;
  waitpid(job.pid, &status, 0);
  job.pid = -1;

  



  {
    std::string joined;
    joined.reserve(output.size());
    for (size_t i = 0; i < output.size(); ) {
      size_t nl = output.find('\n', i);
      if (nl == std::string::npos) nl = output.size();
      if (i < nl && (output[i] == ' ' || output[i] == '\t') &&
          !joined.empty() && joined.back() != '\n') {
        
        size_t ws = i;
        while (ws < nl && (output[ws] == ' ' || output[ws] == '\t')) ws++;
        joined += ' ';
        joined.append(output, ws, nl - ws);
      } else {
        if (!joined.empty()) joined += '\n';
        joined.append(output, i, nl - i);
      }
      i = nl + 1;
    }
    output = joined;
  }

  
  size_t line_start = 0;
  while (line_start < output.size()) {
    size_t line_end = output.find('\n', line_start);
    if (line_end == std::string::npos) line_end = output.size();
    if (line_end - line_start > 4 &&
        output.compare(line_start, 4, "cnf(") == 0) {
      const char *line = output.c_str() + line_start;
      size_t llen = line_end - line_start;
      const char *p = line + 4;
      const char *end = line + llen;
      int depth = 0, comma_count = 0;
      const char *body_start = NULL, *body_end = NULL;
      for (; p < end; p++) {
        if (*p == '(' || *p == '[') depth++;
        else if (*p == ')' || *p == ']') {
          if (depth == 0) { body_end = p; break; }
          depth--;
        } else if (*p == ',' && depth == 0) {
          comma_count++;
          if (comma_count == 2) body_start = p + 1;
          else if (comma_count == 3) { body_end = p; break; }
        }
      }
      if (body_start && body_end && body_end > body_start) {
        std::string body(body_start, body_end - body_start);
        strim(body);
        while (body.size() >= 2 && body.front() == '(' && body.back() == ')') {
          int d = 0; bool ok = true;
          for (size_t i = 0; i + 1 < body.size(); i++) {
            if (body[i] == '(') d++;
            else if (body[i] == ')') { d--; if (d == 0) { ok = false; break; } }
          }
          if (ok) body = body.substr(1, body.size() - 2);
          else break;
        }
        if (!body.empty()) clauses.push_back(body);
      }
    }
    line_start = line_end + 1;
  }
  return clauses;
}




static void split_top_conjuncts(const Node *n, std::vector<const Node *> &out) {
  if (!n) return;
  if (n->kind == NK_AND) {
    for (size_t i = 0; i < n->children.size(); i++)
      split_top_conjuncts(n->children[i], out);
    return;
  }
  if (n->kind == NK_FORALL && !n->children.empty()) {
    split_top_conjuncts(n->children[0], out);
    return;
  }
  out.push_back(n);
}




static bool is_skolemize_rule(const std::string &rule, bool strict = false) {
  if (strict)
    return rule == "skolemize";
  return rule == "skolemize" || rule == "skolemisation" ||
         rule == "skolemization";
}


static std::string normalize_ws(const std::string &s) {
  std::string r;
  for (size_t i = 0; i < s.size(); i++) {
    if (s[i] != ' ' && s[i] != '\n' && s[i] != '\r' && s[i] != '\t')
      r += s[i];
  }
  return r;
}





static bool body_normalizes_to_false(const std::string &body) {
  std::string nb = normalize_ws(body);
  while (nb.size() >= 2 && nb[0] == '(' && nb[nb.size()-1] == ')') {
    std::string inner = nb.substr(1, nb.size() - 2);
    int d = 0; bool ok = true;
    for (size_t j = 0; j < inner.size(); j++) {
      if (inner[j] == '(') d++;
      else if (inner[j] == ')') { d--; if (d<0) { ok=false; break; } }
    }
    if (ok && d == 0) nb = inner; else break;
  }
  return nb == "$false" || nb == "false";
}


static std::vector<std::string> extract_new_skolems(const std::string &info) {
  std::vector<std::string> result;
  size_t p = info.find("new_symbols(skolem,");
  if (p == std::string::npos)
    p = info.find("new_symbols(skolem ,");
  if (p == std::string::npos) return result;
  size_t b1 = info.find('[', p);
  if (b1 == std::string::npos) return result;
  size_t b2 = info.find(']', b1);
  if (b2 == std::string::npos) return result;
  std::string syms = info.substr(b1 + 1, b2 - b1 - 1);
  
  size_t start = 0;
  for (size_t i = 0; i <= syms.size(); i++) {
    if (i == syms.size() || syms[i] == ',') {
      std::string s = syms.substr(start, i - start);
      strim(s);
      if (!s.empty()) result.push_back(s);
      start = i + 1;
    }
  }
  return result;
}

















static std::vector<std::string> extract_new_naming_symbols(const std::string &info) {
  std::vector<std::string> result;
  








  std::string ninfo = normalize_ws(info);
  size_t p = ninfo.find("new_symbols(naming,");
  if (p == std::string::npos)
    p = ninfo.find("new_symbols(definition,");
  if (p == std::string::npos) return result;
  size_t b1 = ninfo.find('[', p);
  if (b1 == std::string::npos) return result;
  size_t b2 = ninfo.find(']', b1);
  if (b2 == std::string::npos) return result;
  std::string syms = ninfo.substr(b1 + 1, b2 - b1 - 1);
  size_t start = 0;
  for (size_t i = 0; i <= syms.size(); i++) {
    if (i == syms.size() || syms[i] == ',') {
      std::string s = syms.substr(start, i - start);
      strim(s);
      if (!s.empty()) result.push_back(s);
      start = i + 1;
    }
  }
  return result;
}


static std::string extract_new_skolem(const std::string &info) {
  std::vector<std::string> syms = extract_new_skolems(info);
  if (syms.empty()) return "";
  std::string all;
  for (size_t i = 0; i < syms.size(); i++) {
    if (i > 0) all += ",";
    all += syms[i];
  }
  return all;
}










static std::vector<std::string> extract_all_statuses(const std::string &info) {
  std::vector<std::string> out;
  size_t p = 0;
  while ((p = info.find("status(", p)) != std::string::npos) {
    if (p > 0 && (isalnum((unsigned char) info[p - 1]) || info[p - 1] == '_')) {
      p += 7;
      continue;
    }
    size_t open = p + 7;
    size_t close = info.find(')', open);
    if (close == std::string::npos) break;
    std::string val = info.substr(open, close - open);
    strim(val);
    out.push_back(val);
    p = close + 1;
  }
  return out;
}






static std::pair<std::string, std::string>
extract_skolemize_record(const std::string &info) {
  size_t p = info.find("skolemize(");
  if (p == std::string::npos)
    return std::make_pair(std::string(), std::string());
  size_t open = p + 10;
  int depth = 1;
  size_t close = open;
  for (size_t j = open; j < info.size(); j++) {
    if (info[j] == '(') depth++;
    else if (info[j] == ')') { depth--; if (depth == 0) { close = j; break; } }
  }
  std::string inner = info.substr(open, close - open);
  int d = 0;
  for (size_t j = 0; j < inner.size(); j++) {
    if (inner[j] == '(' || inner[j] == '[') d++;
    else if (inner[j] == ')' || inner[j] == ']') d--;
    else if (inner[j] == ',' && d == 0) {
      std::string var = inner.substr(0, j);
      std::string term = inner.substr(j + 1);
      strim(var);
      strim(term);
      return std::make_pair(var, term);
    }
  }
  return std::make_pair(std::string(), std::string());
}



static std::string extract_skolemized(const std::string &info) {
  size_t p = info.find("skolemized(");
  if (p == std::string::npos) return extract_skolemize_record(info).first;
  size_t start = p + 11;
  size_t end = info.find(')', start);
  if (end == std::string::npos) return "";
  std::string var = info.substr(start, end - start);
  strim(var);
  return var;
}


static std::vector<std::string> extract_skolem_args(const std::string &term) {
  std::vector<std::string> args;
  size_t paren = term.find('(');
  if (paren == std::string::npos) return args;
  size_t close = term.rfind(')');
  if (close == std::string::npos || close <= paren) return args;
  std::string inner = term.substr(paren + 1, close - paren - 1);
  size_t start = 0;
  int d = 0;
  for (size_t i = 0; i <= inner.size(); i++) {
    if (i == inner.size() || (inner[i] == ',' && d == 0)) {
      std::string a = inner.substr(start, i - start);
      strim(a);
      if (!a.empty()) args.push_back(a);
      start = i + 1;
    } else if (inner[i] == '(') d++;
    else if (inner[i] == ')') d--;
  }
  return args;
}



struct PrefixQuant { bool is_universal; std::string var; };
static std::vector<PrefixQuant> parse_quantifier_prefix(const std::string &body) {
  std::vector<PrefixQuant> result;
  size_t i = 0;
  while (i < body.size()) {
    while (i < body.size() && (body[i] == ' ' || body[i] == '\n' ||
           body[i] == '\r' || body[i] == '\t' || body[i] == '('))
      i++;
    if (i >= body.size()) break;
    bool is_univ;
    if (body[i] == '!') is_univ = true;
    else if (body[i] == '?') is_univ = false;
    else break;
    i++;
    while (i < body.size() && body[i] == ' ') i++;
    if (i >= body.size() || body[i] != '[') break;
    i++;
    while (i < body.size() && body[i] != ']') {
      while (i < body.size() && (body[i] == ' ' || body[i] == ',')) i++;
      if (i >= body.size() || body[i] == ']') break;
      size_t vstart = i;
      while (i < body.size() && body[i] != ',' && body[i] != ']' &&
             body[i] != ' ' && body[i] != ':')
        i++;
      std::string vname = body.substr(vstart, i - vstart);
      while (i < body.size() && body[i] == ' ') i++;
      if (i < body.size() && body[i] == ':') {
        i++;
        while (i < body.size() && body[i] != ',' && body[i] != ']') i++;
      }
      if (!vname.empty()) {
        PrefixQuant qv;
        qv.is_universal = is_univ;
        qv.var = vname;
        result.push_back(qv);
      }
    }
    if (i < body.size() && body[i] == ']') i++;
    while (i < body.size() && (body[i] == ' ' || body[i] == ':')) i++;
  }
  return result;
}



static std::pair<std::string, std::string> extract_bind(const std::string &info) {
  size_t p = info.find("bind(");
  if (p == std::string::npos) return extract_skolemize_record(info);
  size_t open = p + 5;
  int depth = 1;
  size_t close = open;
  for (size_t j = open; j < info.size(); j++) {
    if (info[j] == '(') depth++;
    else if (info[j] == ')') { depth--; if (depth == 0) { close = j; break; } }
  }
  std::string inner = info.substr(open, close - open);
  
  int d = 0;
  for (size_t j = 0; j < inner.size(); j++) {
    if (inner[j] == '(' || inner[j] == '[') d++;
    else if (inner[j] == ')' || inner[j] == ']') d--;
    else if (inner[j] == ',' && d == 0) {
      std::string var = inner.substr(0, j);
      std::string term = inner.substr(j + 1);
      strim(var);
      strim(term);
      return std::make_pair(var, term);
    }
  }
  return std::make_pair(std::string(), std::string());
}









static std::string normalize_vars(const std::string &s) {
  std::string result;
  std::map<std::string, std::string> var_map;
  int next_id = 0;
  size_t i = 0;
  while (i < s.size()) {
    
    if (s[i] == '\'') {
      result += s[i++];
      while (i < s.size() && s[i] != '\'') {
        if (s[i] == '\\' && i + 1 < s.size()) result += s[i++];
        result += s[i++];
      }
      if (i < s.size()) result += s[i++];
      continue;
    }
    
    if ((s[i] >= 'A' && s[i] <= 'Z') || s[i] == '_') {
      size_t vs = i;
      while (i < s.size() && ((s[i] >= 'A' && s[i] <= 'Z') ||
             (s[i] >= 'a' && s[i] <= 'z') ||
             (s[i] >= '0' && s[i] <= '9') || s[i] == '_')) i++;
      std::string var = s.substr(vs, i - vs);
      if (var_map.find(var) == var_map.end()) {
        char buf[16];
        snprintf(buf, sizeof(buf), "V%d", next_id++);
        var_map[var] = buf;
      }
      result += var_map[var];
      continue;
    }
    result += s[i++];
  }
  return result;
}




static std::string strip_outer_parens(const std::string &s) {
  std::string r = s;
  while (r.size() >= 2 && r[0] == '(' && r[r.size()-1] == ')') {
    
    int depth = 0;
    bool spans = true;
    for (size_t i = 0; i < r.size() - 1; i++) {
      if (r[i] == '(') depth++;
      else if (r[i] == ')') depth--;
      if (depth == 0) { spans = false; break; }
    }
    if (!spans) break;
    r = r.substr(1, r.size() - 2);
    
    size_t a = 0, b = r.size();
    while (a < b && (r[a] == ' ' || r[a] == '\t')) a++;
    while (b > a && (r[b-1] == ' ' || r[b-1] == '\t')) b--;
    r = r.substr(a, b - a);
  }
  return r;
}

static std::set<std::string> free_vars(const Node *n);  
static Node *ast_clone(const Node *n, NodePool &pool);  
static Node *distribute_or_and(Node *n, NodePool &pool, size_t limit,
                               bool *hit_limit);         
static Node *to_nnf(const Node *n, NodePool &pool, bool negated);  
static Node *fof_canonicalize(const Node *n, NodePool &pool);  
static std::string node_to_string(const Node *n);  

static int check_negated_conjecture(const ProofStep &neg_step,
                                     const ProofStep &conj_step,
                                     int timeout_sec) {
  






  std::set<std::string> conj_fv;
  {
    NodePool cp;
    try {
      Node *ca = FormulaParser(conj_step.body.c_str(),
                               conj_step.body.size(), cp).parse();
      if (ca) conj_fv = free_vars(ca);
    } catch (PoolExhausted &) {}
  }

  if (conj_fv.empty()) {
    

    std::string neg_norm = strip_outer_parens(normalize_ws(neg_step.body));
    std::string conj_norm = strip_outer_parens(normalize_ws(conj_step.body));
    std::string expected = "~(" + conj_norm + ")";
    if (neg_norm == expected)
      return 1;
    



    
    if (neg_norm.size() > 2 && neg_norm[0] == '~' && neg_norm[1] == '(') {
      std::string inner = neg_norm.substr(2, neg_norm.size() - 3);
      if (strip_outer_parens(inner) == conj_norm)
        return 1;
    }
    





    {
      NodePool np;
      try {
        Node *nb = FormulaParser(neg_step.body.c_str(),
                                 neg_step.body.size(), np).parse();
        Node *cb = FormulaParser(conj_step.body.c_str(),
                                 conj_step.body.size(), np).parse();
        if (nb && cb) {
          Node *neg_nnf = to_nnf(nb, np, false);
          Node *notconj_nnf = to_nnf(cb, np, true);  
          if (neg_nnf && notconj_nnf) {
            Node *a = fof_canonicalize(neg_nnf, np);
            Node *b = fof_canonicalize(notconj_nnf, np);
            if (a && b && node_to_string(a) == node_to_string(b))
              return 1;
          }
        }
      } catch (PoolExhausted &) {}
    }
  }

  


  std::string uc_conj = conj_step.body;
  if (!conj_fv.empty()) {
    std::string vl;
    for (std::set<std::string>::iterator vi = conj_fv.begin();
         vi != conj_fv.end(); ++vi) {
      if (!vl.empty()) vl += ",";
      vl += *vi;
    }
    uc_conj = "! [" + vl + "] : (" + conj_step.body + ")";
  }

  



  int t = timeout_sec > 5 ? 5 : timeout_sec;
  std::string problem = "fof(check, conjecture, (("
    + neg_step.body + ") <=> ~(" + uc_conj + "))).";
  if (run_atp_on_problem(problem, t))
    return 1;

  return 0;
}




static void collect_symbols(const Node *n, std::set<std::string> &syms) {
  if (!n) return;
  if (n->kind == NK_PRED || n->kind == NK_FUNC)
    syms.insert(n->name);
  for (size_t i = 0; i < n->children.size(); i++)
    collect_symbols(n->children[i], syms);
}




static int is_skolem_name(const std::string &nm) {
  if (nm.size() > 3 && nm.compare(0, 3, "esk") == 0) {
    for (size_t i = 3; i < nm.size(); i++)
      if (!isdigit(nm[i]) && nm[i] != '_') return 0;
    return 1;
  }
  if (nm.size() > 2 && (nm.compare(0, 2, "sK") == 0 ||
                         nm.compare(0, 2, "sF") == 0)) {
    for (size_t i = 2; i < nm.size(); i++)
      if (!isdigit(nm[i])) return 0;
    return 1;
  }
  return 0;
}









static bool collect_skolem_arg_names(const Node *n,
                                      std::set<std::string> &names) {
  if (!n) return true;
  if (n->kind == NK_VAR) { names.insert(n->name); return true; }
  if (n->kind == NK_FUNC) {
    if (is_skolem_name(n->name)) return false;
    for (size_t i = 0; i < n->children.size(); i++)
      if (!collect_skolem_arg_names(n->children[i], names)) return false;
    return true;
  }
  

  return true;
}


static Node *to_nnf(const Node *n, NodePool &pool, bool negated);




static bool skolem_ast_eq(const Node *a, const Node *b) {
  if (!a || !b) return a == b;
  if (a->kind != b->kind || a->name != b->name) return false;
  if (a->children.size() != b->children.size()) return false;
  for (size_t i = 0; i < a->children.size(); i++)
    if (!skolem_ast_eq(a->children[i], b->children[i])) return false;
  return true;
}

























static bool Skolem_match_too_deep = false;




static long Skolem_match_work = 0;
static const long SKOLEM_MATCH_WORK_MAX = 200000;

static void ast_flatten(Node *n);  







static Node *split_quant_blocks(Node *n, NodePool &pool) {
  if (!n) return n;
  for (size_t i = 0; i < n->children.size(); i++)
    n->children[i] = split_quant_blocks(n->children[i], pool);
  if ((n->kind == NK_FORALL || n->kind == NK_EXISTS) &&
      n->bound_vars.size() > 1) {
    Node *body = n->children.empty() ? NULL : n->children[0];
    for (size_t i = n->bound_vars.size(); i-- > 1; ) {
      Node *q = pool.alloc(n->kind);
      q->bound_vars.push_back(n->bound_vars[i]);
      if (i < n->bound_sorts.size()) q->bound_sorts.push_back(n->bound_sorts[i]);
      if (body) q->children.push_back(body);
      body = q;
    }
    n->bound_vars.resize(1);
    if (n->bound_sorts.size() > 1) n->bound_sorts.resize(1);
    n->children.clear();
    if (body) n->children.push_back(body);
  }
  return n;
}















































static void rename_shadowed_foralls(Node *n, std::map<std::string, std::string> &active,
                                    int &counter) {
  if (!n) return;
  if (n->kind == NK_FORALL && !n->bound_vars.empty()) {
    const std::string orig = n->bound_vars[0];
    std::map<std::string, std::string>::iterator it = active.find(orig);
    bool had = it != active.end();
    std::string saved = had ? it->second : std::string();
    std::string fresh;
    if (had) {
      


      char buf[64];
      snprintf(buf, sizeof(buf), "%s#%d", orig.c_str(), ++counter);
      fresh = buf;
      n->bound_vars[0] = fresh;
    } else {
      

      fresh = orig;
    }
    active[orig] = fresh;
    for (size_t i = 0; i < n->children.size(); i++)
      rename_shadowed_foralls(n->children[i], active, counter);
    if (had) active[orig] = saved;
    else active.erase(orig);
    return;
  }
  if (n->kind == NK_EXISTS && !n->bound_vars.empty()) {
    const std::string &orig = n->bound_vars[0];
    std::map<std::string, std::string>::iterator it = active.find(orig);
    bool had = it != active.end();
    std::string saved = had ? it->second : std::string();
    if (had) active.erase(orig);
    for (size_t i = 0; i < n->children.size(); i++)
      rename_shadowed_foralls(n->children[i], active, counter);
    if (had) active[orig] = saved;
    return;
  }
  if (n->kind == NK_VAR) {
    std::map<std::string, std::string>::iterator it = active.find(n->name);
    if (it != active.end()) n->name = it->second;
    return;
  }
  for (size_t i = 0; i < n->children.size(); i++)
    rename_shadowed_foralls(n->children[i], active, counter);
}

static bool ast_match_skolem_assoc(const Node *parent, const Node *step,
                                   size_t pi, size_t sj, NodePool &pool,
                                   std::set<std::string> &universals,
                                   std::set<std::string> &preserved_existentials,
                                   std::map<std::string, std::string> &var_rename,
                                   std::map<std::string, const Node *> &skolem_map,
                                   std::map<std::string, std::set<std::string> > &skolem_scope,
                                   std::map<std::string, std::set<std::string> > &skolem_preserved_scope,
                                   std::map<std::string, std::set<std::string> > &skolem_required_univs,
                                   std::map<std::string, std::string> &skolem_sorts,
                                   std::set<std::string> &new_skolems,
                                   const std::set<std::string> &declared_new_symbol_names,
                                   int depth);  

static bool ast_match_skolem(const Node *parent, const Node *step,
                             NodePool &pool,
                             std::set<std::string> &universals,
                             std::set<std::string> &preserved_existentials,
                             std::map<std::string, std::string> &var_rename,
                             std::map<std::string, const Node *> &skolem_map,
                             std::map<std::string, std::set<std::string> > &skolem_scope,
                             std::map<std::string, std::set<std::string> > &skolem_preserved_scope,
                             std::map<std::string, std::set<std::string> > &skolem_required_univs,
                             std::map<std::string, std::string> &skolem_sorts,
                             std::set<std::string> &new_skolems,
                             const std::set<std::string> &declared_new_symbol_names,
                             int depth) {
  



  if (depth > 5000) {
    Skolem_match_too_deep = true;
    return false;
  }
  if (!parent || !step) return parent == step;

  











  if (parent->kind == NK_EXISTS) {
    if (parent->children.empty()) return false;
    



    {
      std::map<std::string, const Node *> saved_skolem = skolem_map;
      std::map<std::string, std::set<std::string> > saved_scope = skolem_scope;
      std::map<std::string, std::set<std::string> > saved_preserved_scope = skolem_preserved_scope;
      std::map<std::string, std::set<std::string> > saved_required_univs = skolem_required_univs;
      std::map<std::string, std::string> saved_sorts = skolem_sorts;
      std::set<std::string> saved_new = new_skolems;
      










      std::set<std::string> body_free = free_vars(parent->children[0]);
      for (size_t vi = 0; vi < parent->bound_vars.size(); vi++) {
        skolem_map[parent->bound_vars[vi]] = NULL;
        skolem_scope[parent->bound_vars[vi]] = universals;
        std::set<std::string> req;
        for (std::set<std::string>::const_iterator ui = universals.begin();
             ui != universals.end(); ++ui)
          if (body_free.count(*ui)) req.insert(*ui);
        skolem_required_univs[parent->bound_vars[vi]] = req;
        






        skolem_preserved_scope[parent->bound_vars[vi]] = preserved_existentials;
        



        skolem_sorts[parent->bound_vars[vi]] =
            (vi < parent->bound_sorts.size()) ? parent->bound_sorts[vi]
                                               : std::string();
      }
      if (ast_match_skolem(parent->children[0], step, pool, universals,
                           preserved_existentials, var_rename, skolem_map,
                           skolem_scope, skolem_preserved_scope,
                           skolem_required_univs, skolem_sorts,
                           new_skolems, declared_new_symbol_names, depth + 1))
        return true;
      skolem_map = saved_skolem;
      skolem_scope = saved_scope;
      skolem_preserved_scope = saved_preserved_scope;
      skolem_required_univs = saved_required_univs;
      skolem_sorts = saved_sorts;
      new_skolems = saved_new;
    }
    


    if (step->kind == NK_EXISTS &&
        parent->bound_vars.size() == step->bound_vars.size() &&
        !step->children.empty()) {
      std::map<std::string, std::string> saved_rename = var_rename;
      std::set<std::string> saved_preserved = preserved_existentials;
      std::vector<std::pair<std::string, const Node *> > shadowed;
      for (size_t vi = 0; vi < parent->bound_vars.size(); vi++) {
        var_rename[parent->bound_vars[vi]] = step->bound_vars[vi];
        







        preserved_existentials.insert(parent->bound_vars[vi]);
        std::map<std::string, const Node *>::iterator si =
            skolem_map.find(parent->bound_vars[vi]);
        if (si != skolem_map.end()) {
          shadowed.push_back(std::make_pair(si->first, si->second));
          skolem_map.erase(si);
        }
      }
      bool ok = ast_match_skolem(parent->children[0], step->children[0],
                                  pool, universals, preserved_existentials,
                                  var_rename, skolem_map, skolem_scope,
                                  skolem_preserved_scope, skolem_required_univs,
                                  skolem_sorts, new_skolems,
                                  declared_new_symbol_names, depth + 1);
      var_rename = saved_rename;
      preserved_existentials = saved_preserved;
      for (size_t si = 0; si < shadowed.size(); si++)
        skolem_map[shadowed[si].first] = shadowed[si].second;
      if (ok) return true;
    }
    return false;
  }

  

  if (parent->kind == NK_FORALL) {
    if (step->kind != NK_FORALL) return false;
    if (parent->bound_vars.size() != step->bound_vars.size()) return false;
    std::map<std::string, std::string> saved_rename = var_rename;
    std::set<std::string> saved_universals = universals;
    


    std::vector<std::pair<std::string, const Node *> > shadowed;
    std::vector<std::pair<std::string, std::string> > shadowed_sorts;
    for (size_t i = 0; i < parent->bound_vars.size(); i++) {
      universals.insert(parent->bound_vars[i]);
      var_rename[parent->bound_vars[i]] = step->bound_vars[i];
      std::map<std::string, const Node *>::iterator si =
          skolem_map.find(parent->bound_vars[i]);
      if (si != skolem_map.end()) {
        shadowed.push_back(std::make_pair(si->first, si->second));
        skolem_map.erase(si);
        std::map<std::string, std::string>::iterator sti =
            skolem_sorts.find(parent->bound_vars[i]);
        if (sti != skolem_sorts.end()) {
          shadowed_sorts.push_back(std::make_pair(sti->first, sti->second));
          skolem_sorts.erase(sti);
        }
      }
    }
    if (parent->children.empty() || step->children.empty()) return false;
    bool ok = ast_match_skolem(parent->children[0], step->children[0],
                                pool, universals, preserved_existentials,
                                var_rename, skolem_map, skolem_scope,
                                skolem_preserved_scope, skolem_required_univs,
                                skolem_sorts,
                                new_skolems, declared_new_symbol_names,
                                depth + 1);
    var_rename = saved_rename;
    universals = saved_universals;
    for (size_t si = 0; si < shadowed_sorts.size(); si++)
      skolem_sorts[shadowed_sorts[si].first] = shadowed_sorts[si].second;
    for (size_t si = 0; si < shadowed.size(); si++)
      skolem_map[shadowed[si].first] = shadowed[si].second;
    return ok;
  }

  

  if (parent->kind == NK_VAR) {
    std::map<std::string, const Node *>::iterator it =
        skolem_map.find(parent->name);
    if (it != skolem_map.end()) {
      




      std::map<std::string, std::set<std::string> >::iterator scope_it =
          skolem_scope.find(parent->name);
      const std::set<std::string> &skolem_univs =
          (scope_it != skolem_scope.end()) ? scope_it->second : universals;
      





      std::map<std::string, std::set<std::string> >::iterator req_it =
          skolem_required_univs.find(parent->name);
      const std::set<std::string> &skolem_req_univs =
          (req_it != skolem_required_univs.end()) ? req_it->second : skolem_univs;
      if (it->second == NULL) {
        
        if (step->kind == NK_FUNC) {
          







          if (!is_skolem_name(step->name) &&
              !declared_new_symbol_names.count(step->name))
            return false;
          new_skolems.insert(step->name);
          



          std::set<std::string> step_universals;
          for (std::set<std::string>::const_iterator ui = skolem_req_univs.begin();
               ui != skolem_req_univs.end(); ++ui) {
            std::map<std::string, std::string>::iterator ri =
                var_rename.find(*ui);
            step_universals.insert(ri != var_rename.end() ? ri->second : *ui);
          }
          








          std::set<std::string> step_preserved;
          for (std::set<std::string>::const_iterator ui = skolem_univs.begin();
               ui != skolem_univs.end(); ++ui) {
            std::map<std::string, std::string>::iterator ri =
                var_rename.find(*ui);
            step_preserved.insert(ri != var_rename.end() ? ri->second : *ui);
          }
          std::map<std::string, std::set<std::string> >::iterator pscope_it =
              skolem_preserved_scope.find(parent->name);
          if (pscope_it != skolem_preserved_scope.end()) {
            for (std::set<std::string>::const_iterator ei =
                     pscope_it->second.begin();
                 ei != pscope_it->second.end(); ++ei) {
              std::map<std::string, std::string>::iterator ri =
                  var_rename.find(*ei);
              step_preserved.insert(ri != var_rename.end() ? ri->second : *ei);
            }
          }
          



          std::set<std::string> referenced;
          for (size_t i = 0; i < step->children.size(); i++) {
            if (!collect_skolem_arg_names(step->children[i], referenced))
              return false;
          }
          


          for (std::set<std::string>::const_iterator ui =
                   step_universals.begin();
               ui != step_universals.end(); ++ui) {
            if (referenced.find(*ui) == referenced.end()) return false;
          }
          


          for (std::set<std::string>::const_iterator ni = referenced.begin();
               ni != referenced.end(); ++ni) {
            if (step_universals.find(*ni) == step_universals.end() &&
                step_preserved.find(*ni) == step_preserved.end())
              return false;
          }
        } else if (step->kind == NK_VAR) {
          

          if (!skolem_univs.empty()) return false;
          if (!is_skolem_name(step->name)) return false;
          new_skolems.insert(step->name);
        } else {
          return false;
        }
        























        {
          std::map<std::string, std::string>::const_iterator sortit =
              skolem_sorts.find(parent->name);
          std::string expected = (sortit != skolem_sorts.end()) ? sortit->second
                                                                 : std::string();
          if (!expected.empty()) {
            std::map<std::string, SymbolType>::const_iterator symit =
                Proof_symbol_types.find(step->name);
            bool declared = (symit != Proof_symbol_types.end() &&
                             !symit->second.ret_sort.empty());
            if (declared) {
              if (symit->second.ret_sort != expected)
                return false;
            } else if (expected != "$i") {
              return false;
            }
          }
        }
        it->second = step;
        return true;
      } else {
        
        return skolem_ast_eq(it->second, step);
      }
    }
    
    if (step->kind != NK_VAR) return false;
    std::map<std::string, std::string>::iterator ri =
        var_rename.find(parent->name);
    if (ri != var_rename.end())
      return ri->second == step->name;
    return parent->name == step->name;
  }

  
  if (parent->kind != step->kind) return false;
  if (parent->name != step->name) return false;
  if ((parent->kind == NK_AND || parent->kind == NK_OR) &&
      parent->children.size() != step->children.size())
    



    return ast_match_skolem_assoc(parent, step, 0, 0, pool, universals,
                                  preserved_existentials, var_rename,
                                  skolem_map, skolem_scope,
                                  skolem_preserved_scope, skolem_required_univs,
                                  skolem_sorts, new_skolems,
                                  declared_new_symbol_names, depth);
  if (parent->children.size() != step->children.size()) return false;
  for (size_t i = 0; i < parent->children.size(); i++) {
    if (!ast_match_skolem(parent->children[i], step->children[i],
                          pool, universals, preserved_existentials,
                          var_rename, skolem_map, skolem_scope,
                          skolem_preserved_scope, skolem_required_univs,
                          skolem_sorts, new_skolems, declared_new_symbol_names,
                          depth + 1))
      return false;
  }
  return true;
}








static bool ast_match_skolem_assoc(const Node *parent, const Node *step,
                                   size_t pi, size_t sj, NodePool &pool,
                                   std::set<std::string> &universals,
                                   std::set<std::string> &preserved_existentials,
                                   std::map<std::string, std::string> &var_rename,
                                   std::map<std::string, const Node *> &skolem_map,
                                   std::map<std::string, std::set<std::string> > &skolem_scope,
                                   std::map<std::string, std::set<std::string> > &skolem_preserved_scope,
                                   std::map<std::string, std::set<std::string> > &skolem_required_univs,
                                   std::map<std::string, std::string> &skolem_sorts,
                                   std::set<std::string> &new_skolems,
                                   const std::set<std::string> &declared_new_symbol_names,
                                   int depth) {
  size_t np = parent->children.size(), ns = step->children.size();
  if (pi == np && sj == ns) return true;
  if (pi == np || sj == ns) return false;
  if (depth > 5000 || ++Skolem_match_work > SKOLEM_MATCH_WORK_MAX) {
    Skolem_match_too_deep = true;
    return false;
  }
  
  size_t remaining = np - pi - 1;
  size_t max_take = (ns - sj > remaining) ? (ns - sj - remaining) : 0;
  for (size_t k = 1; k <= max_take; k++) {
    std::set<std::string> s_univ = universals;
    std::set<std::string> s_preserved = preserved_existentials;
    std::map<std::string, std::string> s_ren = var_rename;
    std::map<std::string, const Node *> s_map = skolem_map;
    std::map<std::string, std::set<std::string> > s_scope = skolem_scope;
    std::map<std::string, std::set<std::string> > s_preserved_scope = skolem_preserved_scope;
    std::map<std::string, std::set<std::string> > s_required_univs = skolem_required_univs;
    std::map<std::string, std::string> s_sorts = skolem_sorts;
    std::set<std::string> s_new = new_skolems;
    bool ok;
    if (k == 1) {
      ok = ast_match_skolem(parent->children[pi], step->children[sj], pool,
                            universals, preserved_existentials, var_rename,
                            skolem_map, skolem_scope, skolem_preserved_scope,
                            skolem_required_univs, skolem_sorts, new_skolems,
                            declared_new_symbol_names, depth + 1);
    } else {
      Node *grp = pool.alloc(step->kind);
      for (size_t g = 0; g < k; g++)
        grp->children.push_back(step->children[sj + g]);
      ok = ast_match_skolem(parent->children[pi], grp, pool,
                            universals, preserved_existentials, var_rename,
                            skolem_map, skolem_scope, skolem_preserved_scope,
                            skolem_required_univs, skolem_sorts, new_skolems,
                            declared_new_symbol_names, depth + 1);
    }
    if (ok && ast_match_skolem_assoc(parent, step, pi + 1, sj + k, pool,
                                     universals, preserved_existentials,
                                     var_rename, skolem_map, skolem_scope,
                                     skolem_preserved_scope, skolem_required_univs,
                                     skolem_sorts, new_skolems,
                                     declared_new_symbol_names, depth + 1))
      return true;
    if (Skolem_match_too_deep)
      return false;
    universals = s_univ; preserved_existentials = s_preserved;
    var_rename = s_ren; skolem_map = s_map;
    skolem_scope = s_scope; skolem_preserved_scope = s_preserved_scope;
    skolem_required_univs = s_required_univs;
    skolem_sorts = s_sorts; new_skolems = s_new;
  }
  return false;
}

static std::string node_to_string(const Node *n);






static std::string canon_var_names(const std::string &s) {
  std::string out;
  std::map<std::string, std::string> seen;
  size_t i = 0;
  while (i < s.size()) {
    char c = s[i];
    if (isalpha((unsigned char) c) || c == '_') {
      size_t j = i;
      while (j < s.size() &&
             (isalnum((unsigned char) s[j]) || s[j] == '_')) j++;
      std::string tok = s.substr(i, j - i);
      if (isupper((unsigned char) c)) {
        std::map<std::string, std::string>::iterator it = seen.find(tok);
        if (it == seen.end()) {
          char buf[24];
          snprintf(buf, sizeof(buf), "V%zu", seen.size() + 1);
          seen[tok] = buf;
          it = seen.find(tok);
        }
        out += it->second;
      } else {
        out += tok;
      }
      i = j;
    } else {
      out += c;
      i++;
    }
  }
  return out;
}





static bool bound_var_occurs(const Node *n, const std::string &name) {
  if (!n) return false;
  if (n->kind == NK_VAR && n->name == name) return true;
  for (size_t i = 0; i < n->children.size(); i++)
    if (bound_var_occurs(n->children[i], name)) return true;
  return false;
}

static int count_existential_bound_vars(const Node *n) {
  if (!n) return 0;
  int c = 0;
  if (n->kind == NK_EXISTS && !n->children.empty()) {
    




    for (size_t i = 0; i < n->bound_vars.size(); i++)
      if (bound_var_occurs(n->children[0], n->bound_vars[i])) c++;
  }
  for (size_t i = 0; i < n->children.size(); i++)
    c += count_existential_bound_vars(n->children[i]);
  return c;
}












static int count_all_existential_bound_vars(const Node *n) {
  if (!n) return 0;
  int c = 0;
  if (n->kind == NK_EXISTS) c += (int)n->bound_vars.size();
  for (size_t i = 0; i < n->children.size(); i++)
    c += count_all_existential_bound_vars(n->children[i]);
  return c;
}

static int check_skolemization(const ProofStep &step,
                                const std::map<std::string, ProofStep> &clauses,
                                std::set<std::string> &seen_skolems,
                                std::string &reason) {
  









  
  std::string par_body;
  if (!step.parents.empty()) {
    std::map<std::string, ProofStep>::const_iterator pit =
        clauses.find(step.parents[0]);
    if (pit != clauses.end())
      par_body = pit->second.body;
  }

  
  NodePool pool;
  std::set<std::string> par_syms, step_syms;
  Node *par_ast = NULL, *step_ast = NULL;
  try {
    if (!par_body.empty()) {
      par_ast = FormulaParser(par_body.c_str(), par_body.size(), pool).parse();
      if (par_ast) collect_symbols(par_ast, par_syms);
    }
    if (!step.body.empty()) {
      step_ast = FormulaParser(step.body.c_str(), step.body.size(),
                                pool).parse();
      if (step_ast) collect_symbols(step_ast, step_syms);
    }
  } catch (PoolExhausted &) {
    
    reason = "formula too large to parse";
    return -1;
  }

  



  if (par_ast && step_ast) {
    


    Node *par_nnf = NULL;
    try { par_nnf = to_nnf(par_ast, pool, false); }
    catch (PoolExhausted &) { par_nnf = NULL; }
    if (par_nnf == NULL) {
      

      reason = "formula too large to normalize";
      return -1;
    }
    





    Node *step_nnf = NULL;
    try { step_nnf = to_nnf(step_ast, pool, false); }
    catch (PoolExhausted &) { step_nnf = NULL; }
    if (step_nnf == NULL) {
      reason = "formula too large to normalize";
      return -1;
    }
    ast_flatten(par_nnf);
    ast_flatten(step_nnf);
    par_nnf = split_quant_blocks(par_nnf, pool);
    step_nnf = split_quant_blocks(step_nnf, pool);
    



    {
      std::map<std::string, std::string> par_active, step_active;
      int par_ctr = 0, step_ctr = 0;
      rename_shadowed_foralls(par_nnf, par_active, par_ctr);
      rename_shadowed_foralls(step_nnf, step_active, step_ctr);
    }
    std::set<std::string> universals;
    std::map<std::string, std::string> var_rename;
    





    {
      std::set<std::string> par_fv = free_vars(par_nnf);
      for (std::set<std::string>::iterator fi = par_fv.begin();
           fi != par_fv.end(); ++fi) {
        universals.insert(*fi);
        var_rename[*fi] = *fi;
      }
    }
    std::map<std::string, const Node *> skolem_map;
    std::map<std::string, std::set<std::string> > skolem_scope;
    std::map<std::string, std::set<std::string> > skolem_preserved_scope;
    std::map<std::string, std::set<std::string> > skolem_required_univs;
    std::map<std::string, std::string> skolem_sorts;
    std::set<std::string> ast_new_skolems;
    std::set<std::string> preserved_existentials;
    






    std::set<std::string> declared_new_symbol_names;
    {
      std::vector<std::string> dns = extract_new_skolems(step.info);
      for (size_t di = 0; di < dns.size(); di++)
        declared_new_symbol_names.insert(dns[di]);
    }
    Skolem_match_too_deep = false;
    Skolem_match_work = 0;
    bool matched =
        ast_match_skolem(par_nnf, step_nnf, pool, universals,
                         preserved_existentials, var_rename,
                         skolem_map, skolem_scope, skolem_preserved_scope,
                         skolem_required_univs, skolem_sorts, ast_new_skolems,
                         declared_new_symbol_names, 0);
    bool first_too_deep = Skolem_match_too_deep;
    if (!matched && !first_too_deep) {
      









      bool dist_hit_limit = false;
      Node *par_dist = NULL;
      try {
        par_dist = distribute_or_and(ast_clone(par_nnf, pool), pool,
                                     10000, &dist_hit_limit);
        if (par_dist) {
          ast_flatten(par_dist);
          par_dist = split_quant_blocks(par_dist, pool);
        }
      } catch (PoolExhausted &) { par_dist = NULL; }
      if (par_dist && !dist_hit_limit) {
        universals.clear();
        preserved_existentials.clear();
        var_rename.clear();
        skolem_map.clear();
        skolem_scope.clear();
        skolem_preserved_scope.clear();
        skolem_required_univs.clear();
        skolem_sorts.clear();
        ast_new_skolems.clear();
        {
          std::map<std::string, std::string> d_active;
          int d_ctr = 0;
          rename_shadowed_foralls(par_dist, d_active, d_ctr);
        }
        {
          std::set<std::string> par_fv = free_vars(par_dist);
          for (std::set<std::string>::iterator fi = par_fv.begin();
               fi != par_fv.end(); ++fi) {
            universals.insert(*fi);
            var_rename[*fi] = *fi;
          }
        }
        Skolem_match_too_deep = false;
        Skolem_match_work = 0;
        matched =
            ast_match_skolem(par_dist, step_nnf, pool, universals,
                             preserved_existentials, var_rename,
                             skolem_map, skolem_scope,
                             skolem_preserved_scope, skolem_required_univs,
                             skolem_sorts, ast_new_skolems,
                             declared_new_symbol_names, 0);
      }
    }
    if (!matched) {
      if (Skolem_match_too_deep || first_too_deep) {
        
        reason = "formula too deep to verify structurally";
        return -1;
      }
      reason = "Skolemization structural mismatch: formula is not a valid "
               "Skolemization of parent (wrong constant/function arity, "
               "injected formula, or missing quantifier)";
      return 0;
    }
    








    {
      int pe = count_existential_bound_vars(par_nnf);
      int se = count_existential_bound_vars(step_nnf);
      if (pe - se > (int)ast_new_skolems.size()) {
        reason = "Skolemization collapses independent existentials onto one "
                 "Skolem symbol (distinct existentials require distinct "
                 "Skolem symbols)";
        return 0;
      }
    }
    


    for (std::set<std::string>::iterator it = ast_new_skolems.begin();
         it != ast_new_skolems.end(); ++it) {
      if (seen_skolems.count(*it)) {
        reason = "Skolem symbol '" + *it + "' introduced more than once";
        return 0;
      }
      if (Problem_symbols.count(*it)) {
        reason = "introduced Skolem symbol '" + *it
                 + "' already occurs in the problem";
        return 0;
      }
      seen_skolems.insert(*it);
    }
    







    {
      std::pair<std::string, std::string> ann = extract_bind(step.info);
      std::string ann_var = extract_skolemized(step.info);
      if (ann_var.empty()) ann_var = ann.first;
      std::vector<std::string> declared = extract_new_skolems(step.info);
      


















      if (Strict_verification && !ast_new_skolems.empty()) {
        if (declared.empty()) {
          reason = "skolemize step carries no new_symbols(skolem, [sK]) "
                   "record -- cannot confirm strict-mode record conformance "
                   "(TPTP grammar makes this record optional; not evidence "
                   "the Skolemization itself is wrong)";
          return -1;
        }
        std::pair<std::string, std::string> skrec =
            extract_skolemize_record(step.info);
        if (skrec.first.empty() || skrec.second.empty()) {
          reason = "skolemize step does not carry the mandated "
                   "skolemize(Var, sK(...)) record (uses the older "
                   "skolemized(Var)+bind(Var, Term) form, or none) -- "
                   "cannot confirm strict-mode record conformance";
          return -1;
        }
        

        for (std::set<std::string>::iterator ni = ast_new_skolems.begin();
             ni != ast_new_skolems.end(); ++ni) {
          bool listed = false;
          for (size_t di = 0; di < declared.size(); di++) {
            std::string d;
            for (size_t ci = 0; ci < declared[di].size(); ci++)
              if (declared[di][ci] != '\'') d += declared[di][ci];
            if (d == *ni) { listed = true; break; }
          }
          if (!listed) {
            reason = "introduced Skolem symbol '" + *ni + "' is not listed in "
                     "the new_symbols(skolem, [...]) record";
            return 0;
          }
        }
      }
      








      int vacuous_budget = count_all_existential_bound_vars(par_nnf) -
                            count_existential_bound_vars(par_nnf);
      for (size_t di = 0; di < declared.size(); di++) {
        std::string d;
        for (size_t ci = 0; ci < declared[di].size(); ci++)
          if (declared[di][ci] != '\'') d += declared[di][ci];
        if (!ast_new_skolems.count(d)) {
          if (vacuous_budget > 0) { vacuous_budget--; continue; }
          reason = "declared Skolem '" + declared[di]
                   + "' was not introduced by this step "
                     "(annotation/result mismatch)";
          return 0;
        }
      }
      if (!ann_var.empty() && skolem_map.empty()) {
        reason = "annotation claims variable '" + ann_var
                 + "' was Skolemized, but the result formula equals the "
                   "parent (nothing was Skolemized)";
        return 0;
      }
      if (!ann_var.empty() && !skolem_map.empty()) {
        std::map<std::string, const Node *>::const_iterator mi =
            skolem_map.find(ann_var);
        if (mi == skolem_map.end()) {
          reason = "annotation claims variable '" + ann_var
                   + "' was Skolemized, but the result formula Skolemizes "
                     "a different variable";
          return 0;
        }
        if (!ann.second.empty() && mi->second != NULL) {
          std::string used = node_to_string(mi->second);
          std::string claimed = ann.second;
          std::string used_n, claimed_n;
          for (size_t ci = 0; ci < used.size(); ci++)
            if (!isspace((unsigned char) used[ci]) && used[ci] != '\'')
              used_n += used[ci];
          for (size_t ci = 0; ci < claimed.size(); ci++)
            if (!isspace((unsigned char) claimed[ci]) && claimed[ci] != '\'')
              claimed_n += claimed[ci];
          if (used_n != claimed_n &&
              canon_var_names(used_n) != canon_var_names(claimed_n)) {
            reason = "bind term '" + claimed
                     + "' does not match the substitution actually applied ('"
                     + used + "')";
            return 0;
          }
        }
      }
    }
    return 1;  
  }

  

  
  std::vector<std::string> new_syms;
  for (std::set<std::string>::iterator it = step_syms.begin();
       it != step_syms.end(); ++it) {
    if (par_syms.find(*it) == par_syms.end()) {
      
      if (!is_skolem_name(*it)) {
        reason = "new symbol '" + *it + "' is not a valid Skolem name";
        return 0;
      }
      if (Problem_symbols.count(*it)) {
        reason = "introduced Skolem symbol '" + *it
                 + "' already occurs in the problem";
        return 0;
      }
      if (seen_skolems.count(*it)) {
        reason = "Skolem symbol '" + *it + "' reused from a prior step";
        return 0;
      }
      new_syms.push_back(*it);
    }
  }

  
  for (size_t i = 0; i < new_syms.size(); i++)
    seen_skolems.insert(new_syms[i]);

  


  if (par_ast && step_ast) {
    std::set<std::string> par_preds, step_preds;
    std::vector<const Node *> wk;
    wk.push_back(par_ast);
    while (!wk.empty()) {
      const Node *cn = wk.back(); wk.pop_back();
      if (!cn) continue;
      if (cn->kind == NK_PRED) par_preds.insert(cn->name);
      for (size_t ci = 0; ci < cn->children.size(); ci++)
        wk.push_back(cn->children[ci]);
    }
    wk.push_back(step_ast);
    while (!wk.empty()) {
      const Node *cn = wk.back(); wk.pop_back();
      if (!cn) continue;
      if (cn->kind == NK_PRED) step_preds.insert(cn->name);
      for (size_t ci = 0; ci < cn->children.size(); ci++)
        wk.push_back(cn->children[ci]);
    }
    
    for (std::set<std::string>::iterator it = step_preds.begin();
         it != step_preds.end(); ++it) {
      if (par_preds.find(*it) == par_preds.end()) {
        reason = "Skolemize introduces new predicate '" + *it + "'";
        return 0;
      }
    }
  }

  



  std::vector<std::string> skolem_syms = extract_new_skolems(step.info);
  for (size_t i = 0; i < skolem_syms.size(); i++) {
    const std::string &sym = skolem_syms[i];
    bool from_this_step = false;
    for (size_t j = 0; j < new_syms.size(); j++)
      if (new_syms[j] == sym) { from_this_step = true; break; }
    if (seen_skolems.count(sym) && !from_this_step) {
      reason = "Skolem symbol '" + sym + "' introduced more than once";
      return 0;
    }
    seen_skolems.insert(sym);
    if (step.body.find(sym) == std::string::npos) {
      reason = "declared Skolem '" + sym + "' absent from result formula";
      return 0;
    }
  }

  std::pair<std::string, std::string> bind_pair = extract_bind(step.info);
  if (!bind_pair.first.empty() && !bind_pair.second.empty()) {
    bool found = false;
    std::vector<std::string> &check_syms =
        skolem_syms.empty() ? new_syms : skolem_syms;
    for (size_t i = 0; i < check_syms.size(); i++) {
      if (bind_pair.second.find(check_syms[i]) != std::string::npos) {
        found = true;
        break;
      }
    }
    if (!found && !check_syms.empty()) {
      reason = "bind term '" + bind_pair.second
               + "' does not use any Skolem symbol";
      return 0;
    }
  }

  

  std::string skolemized_var = extract_skolemized(step.info);
  if (!skolemized_var.empty() && !bind_pair.second.empty() &&
      !par_body.empty()) {
    std::vector<PrefixQuant> prefix = parse_quantifier_prefix(par_body);
    std::set<std::string> expected;
    for (size_t i = 0; i < prefix.size(); i++) {
      if (prefix[i].var == skolemized_var) break;
      if (prefix[i].is_universal) expected.insert(prefix[i].var);
    }
    std::vector<std::string> actual =
        extract_skolem_args(bind_pair.second);
    for (size_t i = 0; i < actual.size(); i++) {
      if (expected.find(actual[i]) == expected.end()) {
        reason = "Skolem argument '" + actual[i]
                 + "' is not a universally quantified variable in scope";
        return 0;
      }
    }
    if (!expected.empty() && actual.empty()) {
      reason = "Skolem is a constant but existential is under "
               "universal quantifier(s)";
      return 0;
    }
  }

  return 1;
}




static bool is_fof_preprocess_rule(const std::string &rule) {
  return rule == "variable_rename" || rule == "fof_nnf" ||
         rule == "split_equiv"     || rule == "distribute" ||
         rule == "shift_quantors"  || rule == "fof_simplification" ||
         rule == "apply_def";
}


static bool is_z3_fof_rule(const std::string &rule) {
  return rule == "and_elim"     || rule == "not_or_elim" ||
         rule == "mp"           || rule == "resolve" ||
         rule == "cong"         || rule == "trans" ||
         rule == "def_axiom"    || rule == "nnf" ||
         rule == "quant_intro"  || rule == "inst" ||
         rule == "sk"           || rule == "symm" ||
         rule == "lemma"        || rule == "pull_quant";
}



static bool is_arith_evaluation_rule(const std::string &rule) {
  return rule == "arith_evaluation";
}

static bool is_arith_conflict_rule(const std::string &rule) {
  return rule == "arith_conflict";
}
















typedef __int128 Int128;
typedef unsigned __int128 UInt128;

static const Int128 kArithSafeBound = ((Int128)1) << 100;

static bool int128_in_range(Int128 v) {
  Int128 a = v < 0 ? -v : v;
  return a <= kArithSafeBound;
}

static bool int128_add_safe(Int128 a, Int128 b, Int128 &out) {
  if (!int128_in_range(a) || !int128_in_range(b)) return false;
  out = a + b;
  return int128_in_range(out);
}

static bool int128_mul_safe(Int128 a, Int128 b, Int128 &out) {
  if (!int128_in_range(a) || !int128_in_range(b)) return false;
  if (a == 0 || b == 0) { out = 0; return true; }
  Int128 aa = a < 0 ? -a : a, bb = b < 0 ? -b : b;
  if (aa > kArithSafeBound / bb) return false;  
  out = a * b;
  return true;
}

static Int128 int128_gcd(Int128 a, Int128 b) {
  if (a < 0) a = -a;
  if (b < 0) b = -b;
  while (b != 0) { Int128 t = a % b; a = b; b = t; }
  return a;
}





struct Rational {
  Int128 num;
  Int128 den;
  bool ok;
  Rational() : num(0), den(1), ok(true) {}
  explicit Rational(long long v) : num(v), den(1), ok(true) {}
  Rational(Int128 n, Int128 d, bool o) : num(n), den(d), ok(o) {
    if (ok) normalize();
  }
  void normalize() {
    if (den == 0) { ok = false; return; }
    if (den < 0) { den = -den; num = -num; }
    if (!int128_in_range(num) || !int128_in_range(den)) { ok = false; return; }
    if (num == 0) { den = 1; return; }
    Int128 g = int128_gcd(num, den);
    if (g > 1) { num /= g; den /= g; }
  }
};










static Rational rat_add(const Rational &a, const Rational &b) {
  if (!a.ok || !b.ok) return Rational(0, 1, false);
  Int128 g = int128_gcd(a.den, b.den);
  if (g < 1) return Rational(0, 1, false);  
  Int128 a_den_reduced = a.den / g;
  Int128 b_den_reduced = b.den / g;
  Int128 lcm, t1, t2, num;
  if (!int128_mul_safe(a_den_reduced, b.den, lcm)) return Rational(0, 1, false);
  if (!int128_mul_safe(a.num, b_den_reduced, t1)) return Rational(0, 1, false);
  if (!int128_mul_safe(b.num, a_den_reduced, t2)) return Rational(0, 1, false);
  if (!int128_add_safe(t1, t2, num)) return Rational(0, 1, false);
  return Rational(num, lcm, true);
}
static Rational rat_neg(const Rational &a) {
  if (!a.ok) return Rational(0, 1, false);
  if (!int128_in_range(-a.num)) return Rational(0, 1, false);
  return Rational(-a.num, a.den, true);
}
static Rational rat_sub(const Rational &a, const Rational &b) {
  return rat_add(a, rat_neg(b));
}






static Rational rat_mul(const Rational &a, const Rational &b) {
  if (!a.ok || !b.ok) return Rational(0, 1, false);
  Int128 g1 = int128_gcd(a.num, b.den);
  Int128 g2 = int128_gcd(b.num, a.den);
  Int128 an = (g1 > 1) ? a.num / g1 : a.num;
  Int128 bd = (g1 > 1) ? b.den / g1 : b.den;
  Int128 bn = (g2 > 1) ? b.num / g2 : b.num;
  Int128 ad = (g2 > 1) ? a.den / g2 : a.den;
  Int128 num, den;
  if (!int128_mul_safe(an, bn, num)) return Rational(0, 1, false);
  if (!int128_mul_safe(ad, bd, den)) return Rational(0, 1, false);
  return Rational(num, den, true);
}
static bool rat_is_zero(const Rational &a) { return a.ok && a.num == 0; }
static bool rat_eq(const Rational &a, const Rational &b) {
  if (!a.ok || !b.ok) return false;
  return a.num == b.num && a.den == b.den;  
}

static int rat_sign(const Rational &a) {
  if (a.num < 0) return -1;
  if (a.num > 0) return 1;
  return 0;
}





static std::string int128_to_string(Int128 v) {
  if (v == 0) return "0";
  bool neg = v < 0;
  UInt128 u = neg ? (UInt128)(-v) : (UInt128)v;
  std::string s;
  while (u > 0) {
    s.push_back((char)('0' + (int)(u % 10)));
    u /= 10;
  }
  if (neg) s.push_back('-');
  std::reverse(s.begin(), s.end());
  return s;
}




static std::string rational_to_string(const Rational &r) {
  if (!r.ok) return "";
  if (r.den == 1) return int128_to_string(r.num);
  return int128_to_string(r.num) + "/" + int128_to_string(r.den);
}



static bool int128_from_digits(const std::string &digits, Int128 &out) {
  out = 0;
  if (digits.empty()) return false;
  for (size_t i = 0; i < digits.size(); i++) {
    if (!isdigit((unsigned char) digits[i])) return false;
    Int128 next;
    if (!int128_mul_safe(out, 10, next)) return false;
    if (!int128_add_safe(next, digits[i] - '0', out)) return false;
  }
  return true;
}








static bool parse_rational(const std::string &text, Rational &out) {
  size_t i = 0, len = text.size();
  bool neg = false;
  if (i < len && (text[i] == '-' || text[i] == '+')) { neg = (text[i] == '-'); i++; }
  size_t int_start = i;
  while (i < len && isdigit((unsigned char) text[i])) i++;
  if (i == int_start) return false;
  std::string int_part = text.substr(int_start, i - int_start);

  
  if (i < len && text[i] == '/') {
    size_t den_start = i + 1;
    size_t j = den_start;
    while (j < len && isdigit((unsigned char) text[j])) j++;
    if (j != len || j == den_start) return false;
    Int128 num, den;
    if (!int128_from_digits(int_part, num)) return false;
    if (!int128_from_digits(text.substr(den_start, j - den_start), den)) return false;
    if (neg) { if (!int128_in_range(-num)) return false; num = -num; }
    out = Rational(num, den, true);
    return out.ok;
  }

  


  std::string frac_part;
  if (i < len && text[i] == '.') {
    i++;
    size_t frac_start = i;
    while (i < len && isdigit((unsigned char) text[i])) i++;
    frac_part = text.substr(frac_start, i - frac_start);
  }
  int exp = 0;
  bool exp_neg = false;
  bool has_exp = false;
  if (i < len && (text[i] == 'e' || text[i] == 'E')) {
    has_exp = true;
    i++;
    if (i < len && (text[i] == '+' || text[i] == '-')) { exp_neg = (text[i] == '-'); i++; }
    size_t exp_start = i;
    while (i < len && isdigit((unsigned char) text[i])) i++;
    if (i == exp_start) return false;
    


    if (i - exp_start > 2) return false;
    int mag = 0;
    for (size_t k = exp_start; k < i; k++) mag = mag * 10 + (text[k] - '0');
    exp = exp_neg ? -mag : mag;
  }
  if (i != len) return false;  
  if (frac_part.empty() && !has_exp) return false;  



  std::string mantissa = int_part + frac_part;
  Int128 mant;
  if (!int128_from_digits(mantissa, mant)) return false;
  if (neg) { if (!int128_in_range(-mant)) return false; mant = -mant; }
  Int128 num = mant, den = 1;
  int scale = exp - (int) frac_part.size();
  while (scale > 0) {
    Int128 next;
    if (!int128_mul_safe(num, 10, next)) return false;
    num = next;
    scale--;
  }
  while (scale < 0) {
    Int128 next;
    if (!int128_mul_safe(den, 10, next)) return false;
    den = next;
    scale++;
  }
  out = Rational(num, den, true);
  return out.ok;
}



static bool parse_rational_or_integer(const std::string &text, Rational &out) {
  size_t i = 0, len = text.size();
  if (i < len && (text[i] == '-' || text[i] == '+')) i++;
  size_t j = i;
  while (j < len && isdigit((unsigned char) text[j])) j++;
  if (j == len && j > i) {
    bool neg = (len > 0 && text[0] == '-');
    Int128 v;
    if (!int128_from_digits(text.substr(i, j - i), v)) return false;
    if (neg) { if (!int128_in_range(-v)) return false; v = -v; }
    out = Rational(v, 1, true);
    return true;
  }
  return parse_rational(text, out);
}





struct LinearForm {
  std::map<std::string, Rational> coeffs;
  Rational k;
};

static void lf_add_scaled(LinearForm &out, const LinearForm &in, const Rational &scale) {
  for (std::map<std::string, Rational>::const_iterator it = in.coeffs.begin();
       it != in.coeffs.end(); ++it) {
    Rational term = rat_mul(it->second, scale);
    std::map<std::string, Rational>::iterator ex = out.coeffs.find(it->first);
    Rational newval = (ex == out.coeffs.end()) ? term : rat_add(ex->second, term);
    




    if (rat_is_zero(newval)) {
      if (ex != out.coeffs.end()) out.coeffs.erase(ex);
    } else {
      out.coeffs[it->first] = newval;
    }
  }
  out.k = rat_add(out.k, rat_mul(in.k, scale));
}







static std::string canonical_opaque_key(const Node *n);











static bool to_linear_form(const Node *n, LinearForm &out) {
  if (!n) return false;
  if (n->kind == NK_NUMBER) {
    Rational r;
    if (!parse_rational_or_integer(n->name, r) || !r.ok) return false;
    out.k = r;
    return true;
  }
  if (n->kind == NK_FUNC && n->children.size() == 1 && n->name == "$uminus") {
    LinearForm inner;
    if (!to_linear_form(n->children[0], inner)) return false;
    lf_add_scaled(out, inner, Rational(-1));
    return true;
  }
  


  if (n->kind == NK_FUNC && n->children.size() == 1 &&
      (n->name == "$to_rat" || n->name == "$to_real")) {
    return to_linear_form(n->children[0], out);
  }
  







  if (n->kind == NK_FUNC && n->children.size() == 1 && n->name == "$to_int") {
    LinearForm inner;
    if (!to_linear_form(n->children[0], inner)) return false;
    if (inner.coeffs.empty() && inner.k.ok) {
      out.k = Rational(inner.k.num / inner.k.den, 1, true);
      return true;
    }
    

  }
  if (n->kind == NK_FUNC && n->children.size() == 2 &&
      (n->name == "$sum" || n->name == "$difference")) {
    LinearForm a, b;
    if (!to_linear_form(n->children[0], a)) return false;
    if (!to_linear_form(n->children[1], b)) return false;
    lf_add_scaled(out, a, Rational(1));
    lf_add_scaled(out, b, Rational(n->name == "$sum" ? 1 : -1));
    return true;
  }
  if (n->kind == NK_FUNC && n->children.size() == 2 && n->name == "$product") {
    LinearForm a, b;
    if (!to_linear_form(n->children[0], a)) return false;
    if (!to_linear_form(n->children[1], b)) return false;
    if (a.coeffs.empty()) {
      if (!a.k.ok) return false;
      lf_add_scaled(out, b, a.k);
      return true;
    }
    if (b.coeffs.empty()) {
      if (!b.k.ok) return false;
      lf_add_scaled(out, a, b.k);
      return true;
    }
    

  }
  out.coeffs[canonical_opaque_key(n)] = Rational(1);
  return true;
}






static std::string linear_form_to_canonical_string(const LinearForm &lf) {
  std::string s;
  for (std::map<std::string, Rational>::const_iterator it = lf.coeffs.begin();
       it != lf.coeffs.end(); ++it) {
    std::string c = rational_to_string(it->second);
    bool negative = (!c.empty() && c[0] == '-');
    if (!s.empty() && !negative) s += "+";
    if (c == "1") s += it->first;
    else if (c == "-1") s += "-" + it->first;
    else s += c + "*" + it->first;
  }
  if (!rat_is_zero(lf.k) || s.empty()) {
    std::string kstr = rational_to_string(lf.k);
    if (!s.empty() && !kstr.empty() && kstr[0] != '-') s += "+";
    s += kstr;
  }
  return s;
}

















static std::string canonical_opaque_key(const Node *n) {
  if (!n || (n->kind != NK_FUNC && n->kind != NK_PRED) || n->children.empty())
    return node_to_string(n);
  std::string s = n->name + "(";
  for (size_t i = 0; i < n->children.size(); i++) {
    if (i > 0) s += ",";
    LinearForm child_lf;
    if (to_linear_form(n->children[i], child_lf))
      s += linear_form_to_canonical_string(child_lf);
    else
      s += node_to_string(n->children[i]);  
  }
  s += ")";
  return s;
}












static bool normalize_relation(const Node *n, LinearForm &lf, char &rel) {
  if (!n) return false;
  if (n->kind == NK_NOT) {
    if (n->children.size() != 1) return false;
    if (!normalize_relation(n->children[0], lf, rel)) return false;
    LinearForm neg;
    lf_add_scaled(neg, lf, Rational(-1));
    lf = neg;
    if (rel == 'e') rel = 'n';
    else if (rel == 'n') rel = 'e';
    else if (rel == 'l') rel = 't';  
    else if (rel == 't') rel = 'l';  
    else return false;
    return true;
  }
  if (n->kind == NK_EQ || n->kind == NK_NEQ) {
    if (n->children.size() != 2) return false;
    LinearForm a, b;
    if (!to_linear_form(n->children[0], a)) return false;
    if (!to_linear_form(n->children[1], b)) return false;
    lf_add_scaled(lf, a, Rational(1));
    lf_add_scaled(lf, b, Rational(-1));
    rel = (n->kind == NK_EQ) ? 'e' : 'n';
    return true;
  }
  if (n->kind == NK_PRED && n->children.size() == 2 &&
      (n->name == "$less" || n->name == "$lesseq" ||
       n->name == "$greater" || n->name == "$greatereq")) {
    LinearForm a, b;
    if (!to_linear_form(n->children[0], a)) return false;
    if (!to_linear_form(n->children[1], b)) return false;
    bool swap = (n->name == "$greater" || n->name == "$greatereq");
    lf_add_scaled(lf, swap ? b : a, Rational(1));
    lf_add_scaled(lf, swap ? a : b, Rational(-1));
    rel = (n->name == "$less" || n->name == "$greater") ? 't' : 'l';
    return true;
  }
  return false;
}














static bool eval_is_int_or_rat(const Node *n, bool &out) {
  if (!n) return false;
  if (n->kind == NK_NOT) {
    if (n->children.size() != 1) return false;
    bool inner;
    if (!eval_is_int_or_rat(n->children[0], inner)) return false;
    out = !inner;
    return true;
  }
  if (n->kind != NK_PRED || n->children.size() != 1) return false;
  bool want_int;
  if (n->name == "$is_int") want_int = true;
  else if (n->name == "$is_rat") want_int = false;
  else return false;
  LinearForm lf;
  if (!to_linear_form(n->children[0], lf)) return false;
  if (!lf.coeffs.empty() || !lf.k.ok) return false;  
  


  out = want_int ? (lf.k.den == 1) : true;
  return true;
}














static Node *arith_simplify_term(const Node *n, NodePool &pool) {
  if (!n) return NULL;
  LinearForm lf;
  if (to_linear_form(n, lf) && lf.coeffs.empty() && lf.k.ok) {
    std::string text = rational_to_string(lf.k);
    if (!text.empty()) {
      Node *num = pool.alloc(NK_NUMBER);
      num->name = text;
      return num;
    }
  }
  if (n->kind == NK_FUNC || n->kind == NK_PRED) {
    Node *r = pool.alloc(n->kind);
    r->name = n->name;
    for (size_t i = 0; i < n->children.size(); i++)
      r->children.push_back(arith_simplify_term(n->children[i], pool));
    return r;
  }
  return const_cast<Node *>(n);  
}













static int check_arith_argument_rewrite(const Node *par, const Node *step,
                                         NodePool &pool, std::string &reason) {
  int par_nots = 0, step_nots = 0;
  const Node *p = par, *s = step;
  while (p && p->kind == NK_NOT && p->children.size() == 1) { p = p->children[0]; par_nots++; }
  while (s && s->kind == NK_NOT && s->children.size() == 1) { s = s->children[0]; step_nots++; }
  if (!p || !s || par_nots != step_nots) return -1;
  if (p->kind != s->kind) return -1;
  if ((p->kind == NK_PRED || p->kind == NK_FUNC) &&
      (p->name != s->name || p->children.size() != s->children.size()))
    return -1;
  if (p->kind != NK_PRED && p->kind != NK_FUNC &&
      p->kind != NK_EQ && p->kind != NK_NEQ)
    return -1;
  size_t n_args = p->children.size();
  if (s->children.size() != n_args) return -1;
  if (n_args == 0) return -1;  
  for (size_t i = 0; i < n_args; i++) {
    Node *ps = arith_simplify_term(p->children[i], pool);
    Node *ss = arith_simplify_term(s->children[i], pool);
    if (node_to_string(ps) != node_to_string(ss)) {
      reason = "arith_evaluation: argument " + std::to_string(i) +
               " does not simplify to the step's claimed value";
      return 0;
    }
  }
  return 1;
}



















static int check_arith_relation_rewrite(const Node *par_ast, const Node *step_ast,
                                         std::string &reason) {
  LinearForm par_lf, step_lf;
  char par_rel = 0, step_rel = 0;
  if (!normalize_relation(par_ast, par_lf, par_rel) ||
      !normalize_relation(step_ast, step_lf, step_rel)) {
    reason = "arith_evaluation: parent or step is not a recognized "
             "arithmetic relation ($less/$lesseq/$greater/$greatereq/=/!=)";
    return -1;
  }
  if (par_rel != step_rel) {
    reason = "arith_evaluation changed the relation (e.g. < became <=) -- "
             "not a valid ground evaluation or canonical-form rewrite";
    return 0;
  }
  bool is_eq_family = (par_rel == 'e' || par_rel == 'n');

  



  Rational scale;
  bool have_scale = false;
  if (!rat_is_zero(par_lf.k)) {
    if (!par_lf.k.ok || !step_lf.k.ok) { reason = "arithmetic overflow"; return -1; }
    scale = rat_mul(step_lf.k, Rational(par_lf.k.den, par_lf.k.num, true));
    have_scale = true;
  } else {
    for (std::map<std::string, Rational>::const_iterator it = par_lf.coeffs.begin();
         it != par_lf.coeffs.end() && !have_scale; ++it) {
      if (rat_is_zero(it->second)) continue;
      std::map<std::string, Rational>::const_iterator sit = step_lf.coeffs.find(it->first);
      Rational step_val = (sit == step_lf.coeffs.end()) ? Rational(0) : sit->second;
      if (!it->second.ok) { reason = "arithmetic overflow"; return -1; }
      scale = rat_mul(step_val, Rational(it->second.den, it->second.num, true));
      have_scale = true;
    }
  }
  if (!have_scale) {
    

    if (rat_is_zero(step_lf.k) && step_lf.coeffs.empty()) return 1;
    reason = "arith_evaluation: parent reduces to a trivial 0-form but "
             "step does not";
    return 0;
  }
  if (!scale.ok) {
    reason = "arithmetic overflow computing the rescale factor";
    return -1;
  }
  if (rat_is_zero(scale)) {
    







    reason = "arith_evaluation: no consistent nonzero rescaling factor "
             "relates the step to the parent (a pivot term's "
             "coefficient is nonzero in one but zero in the other) -- "
             "not a valid rewrite";
    return 0;
  }
  if (!is_eq_family && rat_sign(scale) < 0) {
    reason = "arith_evaluation: an inequality was rescaled by a negative "
             "factor (would flip its direction) -- not a valid rewrite";
    return 0;
  }

  std::set<std::string> keys;
  for (std::map<std::string, Rational>::const_iterator it = par_lf.coeffs.begin();
       it != par_lf.coeffs.end(); ++it) keys.insert(it->first);
  for (std::map<std::string, Rational>::const_iterator it = step_lf.coeffs.begin();
       it != step_lf.coeffs.end(); ++it) keys.insert(it->first);
  for (std::set<std::string>::const_iterator ki = keys.begin(); ki != keys.end(); ++ki) {
    std::map<std::string, Rational>::const_iterator pi = par_lf.coeffs.find(*ki);
    std::map<std::string, Rational>::const_iterator si = step_lf.coeffs.find(*ki);
    Rational pv = (pi == par_lf.coeffs.end()) ? Rational(0) : pi->second;
    Rational sv = (si == step_lf.coeffs.end()) ? Rational(0) : si->second;
    if (!pv.ok || !sv.ok) { reason = "arithmetic overflow"; return -1; }
    if (!rat_eq(sv, rat_mul(pv, scale))) {
      reason = "arith_evaluation: coefficient of '" + *ki +
               "' does not match the parent under a consistent rescaling";
      return 0;
    }
  }
  Rational expect_k = rat_mul(par_lf.k, scale);
  if (!expect_k.ok || !rat_eq(step_lf.k, expect_k)) {
    reason = "arith_evaluation: constant term does not match the parent "
             "under a consistent rescaling";
    return 0;
  }
  return 1;
}























static int check_arith_clause_discharge(const Node *par, const Node *step,
                                         std::string &reason) {
  std::vector<const Node *> par_lits, step_lits;
  if (par->kind == NK_OR) par_lits.assign(par->children.begin(), par->children.end());
  else par_lits.push_back(par);
  if (step->kind == NK_OR) step_lits.assign(step->children.begin(), step->children.end());
  else if (step->kind != NK_FALSE) step_lits.push_back(step);

  NodePool argpool;  
  size_t si = 0;
  for (size_t pi = 0; pi < par_lits.size(); pi++) {
    const Node *plit = par_lits[pi];
    if (si < step_lits.size() && node_to_string(step_lits[si]) == node_to_string(plit)) {
      si++;
      continue;  
    }
    if (si < step_lits.size()) {
      std::string sub_reason;
      if (check_arith_relation_rewrite(plit, step_lits[si], sub_reason) == 1) {
        si++;
        continue;  
      }
      







      if (check_arith_argument_rewrite(plit, step_lits[si], argpool, sub_reason) == 1) {
        si++;
        continue;  
      }
    }
    LinearForm lf;
    char rel = 0;
    bool decided = false, truth = true;
    if (normalize_relation(plit, lf, rel) && lf.coeffs.empty() && lf.k.ok) {
      int s = rat_sign(lf.k);
      switch (rel) {
        case 'e': truth = (s == 0); break;
        case 'n': truth = (s != 0); break;
        case 'l': truth = (s <= 0); break;
        case 't': truth = (s < 0);  break;
        default: truth = true;  
      }
      decided = true;
    } else if (eval_is_int_or_rat(plit, truth)) {
      




      decided = true;
    }
    if (decided && !truth) continue;  
    return -1;  

  }
  if (si != step_lits.size()) {
    reason = "arith_evaluation: step contains extra literal(s) the parent "
             "does not account for";
    return 0;
  }
  return 1;
}











static void strip_matching_quantifiers(const Node *&par, const Node *&step) {
  while (par && step && par->kind == step->kind &&
         (par->kind == NK_FORALL || par->kind == NK_EXISTS) &&
         par->bound_vars == step->bound_vars &&
         !par->children.empty() && !step->children.empty()) {
    par = par->children[0];
    step = step->children[0];
  }
  













  while (par && par->kind == NK_FORALL && !par->children.empty() &&
         !(step && step->kind == NK_FORALL && par->bound_vars == step->bound_vars)) {
    par = par->children[0];
  }
}




























static bool text_has_unimplemented_arith_vocab(const std::string &s) {
  static const char *toks[] = {
    "$ceiling", "$floor", "$round", "$truncate", "$quotient_e",
    "$quotient_t", "$quotient_f", "$remainder_e", "$remainder_t",
    "$remainder_f", "$quotient", NULL
  };
  for (int i = 0; toks[i]; i++)
    if (s.find(toks[i]) != std::string::npos) return true;
  return false;
}

static int check_arith_evaluation(const ProofStep &step,
                                   const std::map<std::string, ProofStep> &clauses,
                                   std::string &reason) {
  if (step.parents.size() != 1) {
    reason = "arith_evaluation step does not have exactly 1 parent";
    return -1;
  }
  std::map<std::string, ProofStep>::const_iterator pit = clauses.find(step.parents[0]);
  if (pit == clauses.end()) {
    reason = "arith_evaluation step's parent is missing from the proof";
    return -1;
  }
  if (text_has_unimplemented_arith_vocab(pit->second.body) ||
      text_has_unimplemented_arith_vocab(step.body)) {
    reason = "arith_evaluation: parent or step uses an unimplemented "
             "arithmetic construct ($ceiling/$floor/$round/$truncate/"
             "$quotient*/$remainder*) -- cannot verify structurally";
    return -1;
  }
  NodePool pool;
  Node *par_ast = NULL, *step_ast = NULL;
  try {
    par_ast = FormulaParser(pit->second.body.c_str(), pit->second.body.size(), pool).parse();
    step_ast = FormulaParser(step.body.c_str(), step.body.size(), pool).parse();
  } catch (PoolExhausted &) {
    reason = "formula too large to parse";
    return -1;
  }
  if (!par_ast || !step_ast) {
    reason = "arith_evaluation: could not parse parent or step body";
    return -1;
  }
  const Node *par_body = par_ast, *step_body = step_ast;
  strip_matching_quantifiers(par_body, step_body);
  int rc = check_arith_relation_rewrite(par_body, step_body, reason);
  if (rc != -1) return rc;
  std::string reason2;
  int rc2 = check_arith_clause_discharge(par_body, step_body, reason2);
  if (rc2 != -1) { if (rc2 == 0) reason = reason2; return rc2; }
  std::string reason3;
  int rc3 = check_arith_argument_rewrite(par_body, step_body, pool, reason3);
  if (rc3 != -1) { if (rc3 == 0) reason = reason3; return rc3; }
  return -1;
}















static bool is_licensed_arith_fact(const std::string &body) {
  NodePool pool;
  Node *ast = NULL;
  try { ast = FormulaParser(body.c_str(), body.size(), pool).parse(); }
  catch (PoolExhausted &) { return false; }
  if (!ast) return false;
  LinearForm lf;
  char rel = 0;
  if (!normalize_relation(ast, lf, rel)) return false;
  if (!lf.coeffs.empty()) return false;  
  if (!lf.k.ok) return false;
  int s = rat_sign(lf.k);
  switch (rel) {
    case 'e': return s == 0;
    case 'n': return s != 0;
    case 'l': return s <= 0;
    case 't': return s < 0;
    default:  return false;
  }
}




















static bool is_licensed_distinct_object_fact(const std::string &body) {
  std::string b = normalize_ws(body);
  strim(b);
  while (b.size() >= 2 && b.front() == '(' && b.back() == ')') {
    int d = 0; bool ok = true;
    for (size_t j = 0; j < b.size(); j++) {
      if (b[j] == '(') d++;
      else if (b[j] == ')') { d--; if (d == 0 && j != b.size() - 1) { ok = false; break; } }
    }
    if (!ok) break;
    b = b.substr(1, b.size() - 2);
    strim(b);
  }
  if (b.empty() || b[0] != '"') return false;
  size_t end1 = b.find('"', 1);
  if (end1 == std::string::npos) return false;
  std::string lhs = b.substr(0, end1 + 1);
  size_t p = end1 + 1;
  while (p < b.size() && isspace((unsigned char)b[p])) p++;
  bool is_eq;
  if (p < b.size() && b[p] == '=') { is_eq = true; p++; }
  else if (p + 1 < b.size() && b[p] == '!' && b[p+1] == '=') { is_eq = false; p += 2; }
  else return false;
  while (p < b.size() && isspace((unsigned char)b[p])) p++;
  if (p >= b.size() || b[p] != '"') return false;
  size_t end2 = b.find('"', p + 1);
  if (end2 == std::string::npos || end2 + 1 != b.size()) return false;
  std::string rhs = b.substr(p, end2 - p + 1);
  bool same = (lhs == rhs);
  return is_eq ? same : !same;
}








struct ArithConflictPremise {
  std::string name;
  Rational weight;
  char rel;  
};

struct ArithConflictCertificate {
  std::vector<ArithConflictPremise> premises;
  bool strict;
};










static bool parse_arith_conflict_certificate(const std::string &info,
                                              ArithConflictCertificate &out) {
  size_t p = info.find("arith_conflict_certificate(");
  if (p == std::string::npos) return false;
  size_t open_paren = info.find('(', p);
  if (open_paren == std::string::npos) return false;
  size_t close_paren = find_top_level_char(info, ')', open_paren);
  if (close_paren == std::string::npos) return false;
  std::string inner = info.substr(open_paren + 1, close_paren - open_paren - 1);

  size_t comma = find_top_level_char(inner, ',');
  if (comma == std::string::npos) return false;
  std::string premises_text = inner.substr(0, comma);
  std::string strict_text = inner.substr(comma + 1);
  strim(strict_text);
  if (strict_text == "strict") out.strict = true;
  else if (strict_text == "nonstrict") out.strict = false;
  else return false;

  strim(premises_text);
  if (premises_text.size() < 2 || premises_text.front() != '[' ||
      premises_text.back() != ']')
    return false;
  std::string plist = premises_text.substr(1, premises_text.size() - 2);
  std::vector<std::string> triples = split_top_level(plist, ',');
  out.premises.clear();
  for (size_t i = 0; i < triples.size(); i++) {
    std::string t = triples[i];
    strim(t);
    if (t.size() < 2 || t.front() != '[' || t.back() != ']') return false;
    std::vector<std::string> parts = split_top_level(t.substr(1, t.size() - 2), ',');
    if (parts.size() != 3) return false;
    ArithConflictPremise prem;
    prem.name = parts[0];
    strim(prem.name);
    std::string wtext = parts[1];
    strim(wtext);
    if (!parse_rational_or_integer(wtext, prem.weight) || !prem.weight.ok)
      return false;
    std::string rtext = parts[2];
    strim(rtext);
    if (rtext == "eq") prem.rel = 'e';
    else if (rtext == "le") prem.rel = 'l';
    else if (rtext == "lt") prem.rel = 't';
    else return false;
    out.premises.push_back(prem);
  }
  return true;
}

























static int check_arith_conflict(const ProofStep &step,
                                 const std::map<std::string, ProofStep> &clauses,
                                 std::string &reason) {
  ArithConflictCertificate cert;
  if (!parse_arith_conflict_certificate(step.info, cert)) {
    reason = "arith_conflict: no arith_conflict_certificate annotation present";
    return -1;
  }
  if (normalize_ws(step.body) != "$false") {
    reason = "arith_conflict: step conclusion is not $false";
    return 0;
  }
  if (cert.premises.size() != step.parents.size()) {
    reason = "arith_conflict: certificate premise count does not match "
             "the step's parent count";
    return 0;
  }
  std::set<std::string> parent_set(step.parents.begin(), step.parents.end());
  std::set<std::string> cert_set;
  for (size_t i = 0; i < cert.premises.size(); i++)
    cert_set.insert(cert.premises[i].name);
  if (cert_set != parent_set) {
    reason = "arith_conflict: certificate cites different premises than "
             "the step's actual parents";
    return 0;
  }
  for (size_t i = 0; i < cert.premises.size(); i++) {
    std::map<std::string, ProofStep>::const_iterator pit2 =
        clauses.find(cert.premises[i].name);
    if (pit2 != clauses.end() &&
        text_has_unimplemented_arith_vocab(pit2->second.body)) {
      reason = "arith_conflict: premise '" + cert.premises[i].name +
               "' uses an unimplemented arithmetic construct ($ceiling/"
               "$floor/$round/$truncate/$quotient*/$remainder*) -- cannot "
               "verify structurally";
      return -1;
    }
  }

  Rational K(0);
  std::map<std::string, Rational> coeff_sum;
  bool any_lt_nonzero = false;
  for (size_t i = 0; i < cert.premises.size(); i++) {
    const ArithConflictPremise &prem = cert.premises[i];
    std::map<std::string, ProofStep>::const_iterator pit = clauses.find(prem.name);
    if (pit == clauses.end()) {
      reason = "arith_conflict: cited premise '" + prem.name +
               "' is missing from the proof";
      return 0;
    }
    NodePool pool;
    Node *past = NULL;
    try {
      past = FormulaParser(pit->second.body.c_str(), pit->second.body.size(), pool).parse();
    } catch (PoolExhausted &) {
      reason = "formula too large to parse";
      return -1;
    }
    if (!past) {
      reason = "arith_conflict: could not parse premise '" + prem.name + "'";
      return -1;
    }
    LinearForm lf;
    char rel = 0;
    if (!normalize_relation(past, lf, rel)) {
      reason = "arith_conflict: premise '" + prem.name +
               "' is not a recognized arithmetic relation";
      return -1;
    }
    if (rel != prem.rel) {
      reason = "arith_conflict: certificate's relation for '" + prem.name +
               "' does not match the premise's actual relation";
      return 0;
    }
    
    if (!prem.weight.ok) {
      reason = "arithmetic overflow in certificate weight";
      return -1;
    }
    if (rel != 'e' && rat_sign(prem.weight) < 0) {
      reason = "arith_conflict: premise '" + prem.name + "' (a " +
               std::string(rel == 't' ? "strict" : "non-strict") +
               " inequality) has a NEGATIVE weight -- only equality "
               "premises may have a negative weight";
      return 0;
    }
    if (rel == 't' && !rat_is_zero(prem.weight)) any_lt_nonzero = true;

    for (std::map<std::string, Rational>::const_iterator ci = lf.coeffs.begin();
         ci != lf.coeffs.end(); ++ci) {
      Rational term = rat_mul(ci->second, prem.weight);
      std::map<std::string, Rational>::iterator ex = coeff_sum.find(ci->first);
      Rational nv = (ex == coeff_sum.end()) ? term : rat_add(ex->second, term);
      if (!nv.ok) { reason = "arithmetic overflow summing coefficients"; return -1; }
      if (rat_is_zero(nv)) { if (ex != coeff_sum.end()) coeff_sum.erase(ex); }
      else coeff_sum[ci->first] = nv;
    }
    if (!lf.k.ok) { reason = "arithmetic overflow"; return -1; }
    K = rat_add(K, rat_mul(lf.k, prem.weight));
  }
  if (!coeff_sum.empty()) {
    reason = "arith_conflict: premises do not cancel -- '" +
             coeff_sum.begin()->first + "' has a nonzero coefficient after "
             "summing the weighted premises";
    return 0;
  }
  if (!K.ok) {
    reason = "arithmetic overflow summing the certificate";
    return -1;
  }
  if (any_lt_nonzero != cert.strict) {
    reason = "arith_conflict: certificate's strict/nonstrict flag does not "
             "match the derived strictness (whether any lt premise carried "
             "a nonzero weight)";
    return 0;
  }
  











  bool refutation_valid = cert.strict ? (rat_sign(K) >= 0) : (rat_sign(K) > 0);
  if (!refutation_valid) {
    reason = "arith_conflict: the weighted premises do not derive a "
             "contradiction -- K " + std::string(cert.strict ? "< 0" : "<= 0") +
             " remains arithmetically possible";
    return 0;
  }
  return 1;
}


















static bool parse_avatar_guards(const std::string &info,
                                 std::vector<std::string> &out) {
  size_t p = info.find("avatar_guards(");
  if (p == std::string::npos) return false;
  size_t open_paren = info.find('(', p);
  if (open_paren == std::string::npos) return false;
  size_t close_paren = find_top_level_char(info, ')', open_paren);
  if (close_paren == std::string::npos) return false;
  std::string inner = info.substr(open_paren + 1, close_paren - open_paren - 1);
  strim(inner);
  if (inner.size() < 2 || inner.front() != '[' || inner.back() != ']')
    return false;
  std::vector<std::string> names = split_top_level(inner.substr(1, inner.size() - 2), ',');
  out.clear();
  for (size_t i = 0; i < names.size(); i++) {
    std::string n = names[i];
    strim(n);
    if (n.empty()) return false;
    out.push_back(n);
  }
  return !out.empty();
}








static std::string strip_guard_literals(const std::string &body,
                                         const std::set<std::string> &guards,
                                         std::set<std::string> &found_guards) {
  NodePool pool;
  Node *ast = NULL;
  try { ast = FormulaParser(body.c_str(), body.size(), pool).parse(); }
  catch (PoolExhausted &) { return body; }
  if (!ast) return body;
  std::vector<Node *> lits;
  if (ast->kind == NK_OR) {
    for (size_t i = 0; i < ast->children.size(); i++) lits.push_back(ast->children[i]);
  } else {
    lits.push_back(ast);
  }
  std::vector<Node *> remaining;
  for (size_t i = 0; i < lits.size(); i++) {
    Node *l = lits[i];
    if (l->kind == NK_NOT && l->children.size() == 1 &&
        (l->children[0]->kind == NK_PRED || l->children[0]->kind == NK_FUNC ||
         l->children[0]->kind == NK_VAR) &&
        l->children[0]->children.empty() &&
        guards.count(l->children[0]->name)) {
      found_guards.insert(l->children[0]->name);
      continue;  
    }
    remaining.push_back(l);
  }
  if (remaining.size() == lits.size()) return body;  
  if (remaining.empty()) return "$false";
  if (remaining.size() == 1) return node_to_string(remaining[0]);
  Node *nor = pool.alloc(NK_OR);
  for (size_t i = 0; i < remaining.size(); i++) nor->children.push_back(remaining[i]);
  return node_to_string(nor);
}



















static int check_arith_conflict_guarded(const ProofStep &step,
                                         const std::map<std::string, ProofStep> &clauses,
                                         std::string &reason) {
  std::vector<std::string> guard_list;
  if (!parse_avatar_guards(step.info, guard_list))
    return check_arith_conflict(step, clauses, reason);

  std::set<std::string> guards(guard_list.begin(), guard_list.end());
  std::set<std::string> found_in_concl;
  ProofStep stripped_step = step;
  stripped_step.body = strip_guard_literals(step.body, guards, found_in_concl);
  if (found_in_concl.size() != guards.size()) {
    reason = "arith_conflict: avatar_guards declares a guard literal not "
             "present in the step's own conclusion -- malformed record";
    return 0;
  }

  std::map<std::string, ProofStep> stripped_clauses;
  for (size_t i = 0; i < step.parents.size(); i++) {
    std::map<std::string, ProofStep>::const_iterator pit =
        clauses.find(step.parents[i]);
    if (pit == clauses.end()) continue;
    ProofStep pcopy = pit->second;
    std::set<std::string> found_in_prem;  

    pcopy.body = strip_guard_literals(pcopy.body, guards, found_in_prem);
    stripped_clauses[step.parents[i]] = pcopy;
  }
  return check_arith_conflict(stripped_step, stripped_clauses, reason);
}



static Node *ast_clone(const Node *n, NodePool &pool) {
  if (!n) return NULL;
  Node *c = pool.alloc(n->kind);
  c->name = n->name;
  c->bound_vars = n->bound_vars;
  c->bound_sorts = n->bound_sorts;
  for (size_t i = 0; i < n->children.size(); i++)
    c->children.push_back(ast_clone(n->children[i], pool));
  return c;
}

static bool ast_equal(const Node *a, const Node *b) {
  if (!a || !b) return a == b;
  if (a->kind != b->kind) return false;
  if (a->name != b->name) return false;
  if (a->bound_vars != b->bound_vars) return false;
  if (a->children.size() != b->children.size()) return false;
  for (size_t i = 0; i < a->children.size(); i++)
    if (!ast_equal(a->children[i], b->children[i])) return false;
  return true;
}

static void collect_free_vars(const Node *n, std::set<std::string> &bound,
                               std::set<std::string> &free_out) {
  if (!n) return;
  if (n->kind == NK_VAR) {
    if (bound.find(n->name) == bound.end()) free_out.insert(n->name);
    return;
  }
  if (n->kind == NK_FORALL || n->kind == NK_EXISTS) {
    


    std::vector<bool> was_bound;
    for (size_t i = 0; i < n->bound_vars.size(); i++) {
      was_bound.push_back(bound.count(n->bound_vars[i]) > 0);
      bound.insert(n->bound_vars[i]);
    }
    for (size_t i = 0; i < n->children.size(); i++)
      collect_free_vars(n->children[i], bound, free_out);
    for (size_t i = 0; i < n->bound_vars.size(); i++) {
      if (!was_bound[i])
        bound.erase(n->bound_vars[i]);
    }
    return;
  }
  for (size_t i = 0; i < n->children.size(); i++)
    collect_free_vars(n->children[i], bound, free_out);
}

static std::set<std::string> free_vars(const Node *n) {
  std::set<std::string> bound, fv;
  collect_free_vars(n, bound, fv);
  return fv;
}

static size_t ast_size(const Node *n) {
  if (!n) return 0;
  size_t s = 1;
  for (size_t i = 0; i < n->children.size(); i++)
    s += ast_size(n->children[i]);
  return s;
}


static std::string node_to_string(const Node *n) {
  if (!n) return "";
  switch (n->kind) {
    case NK_TRUE:  return "$true";
    case NK_FALSE: return "$false";
    case NK_VAR:   return n->name;
    case NK_QUOTED: return "\"" + n->name + "\"";
    case NK_NUMBER: return n->name;  
    case NK_FUNC:
    case NK_PRED: {
      






      std::string nm = n->name;
      bool needs_q = nm.empty();
      for (size_t i = 0; i < nm.size(); i++) {
        char c = nm[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '_' || c == '$')) {
          needs_q = true; break;
        }
      }
      std::string r = needs_q ? ("'" + nm + "'") : nm;
      if (!n->children.empty()) {
        r += "(";
        for (size_t i = 0; i < n->children.size(); i++) {
          if (i) r += ",";
          r += node_to_string(n->children[i]);
        }
        r += ")";
      }
      return r;
    }
    case NK_NOT:
      return "~(" + node_to_string(n->children[0]) + ")";
    case NK_AND: {
      std::string r = "(";
      for (size_t i = 0; i < n->children.size(); i++) {
        if (i) r += "&";
        r += node_to_string(n->children[i]);
      }
      return r + ")";
    }
    case NK_OR: {
      std::string r = "(";
      for (size_t i = 0; i < n->children.size(); i++) {
        if (i) r += "|";
        r += node_to_string(n->children[i]);
      }
      return r + ")";
    }
    case NK_IMPL:
      return "(" + node_to_string(n->children[0]) + "=>"
                 + node_to_string(n->children[1]) + ")";
    case NK_IFF:
      return "(" + node_to_string(n->children[0]) + "<=>"
                 + node_to_string(n->children[1]) + ")";
    case NK_XOR:
      return "(" + node_to_string(n->children[0]) + "<~>"
                 + node_to_string(n->children[1]) + ")";
    case NK_EQ:
      return "(" + node_to_string(n->children[0]) + "="
                 + node_to_string(n->children[1]) + ")";
    case NK_NEQ:
      return "(" + node_to_string(n->children[0]) + "!="
                 + node_to_string(n->children[1]) + ")";
    case NK_FORALL:
    case NK_EXISTS: {
      std::string r = (n->kind == NK_FORALL) ? "![" : "?[";
      for (size_t i = 0; i < n->bound_vars.size(); i++) {
        if (i) r += ",";
        r += n->bound_vars[i];
      }
      r += "]:(";
      r += node_to_string(n->children[0]);
      r += ")";
      return r;
    }
  }
  return "?";
}
















static bool match_guard_atom(const Node *atom, std::string &var_out,
                              std::string &sort_out) {
  static const std::string prefix = "lamp_sort_";
  if (!atom || atom->kind != NK_PRED) return false;
  if (atom->name.size() <= prefix.size() ||
      atom->name.compare(0, prefix.size(), prefix) != 0)
    return false;
  if (atom->children.size() != 1) return false;
  const Node *arg = atom->children[0];
  if (!arg || arg->kind != NK_VAR) return false;
  sort_out = atom->name.substr(prefix.size());
  var_out = arg->name;
  return true;
}


static void flatten_and_leaves(const Node *n, std::vector<const Node *> &out) {
  if (n && n->kind == NK_AND) {
    for (size_t i = 0; i < n->children.size(); i++)
      flatten_and_leaves(n->children[i], out);
  } else {
    out.push_back(n);
  }
}



























static bool try_demangle_tff1_name(const std::string &name,
                                    std::string &out_base,
                                    std::vector<std::string> &out_type_args) {
  size_t sep = name.find("__");
  if (sep == std::string::npos || sep == 0) return false;
  std::string base = name.substr(0, sep);
  std::map<std::string, SymbolType>::const_iterator it =
      Problem_symbol_types.find(base);
  if (it == Problem_symbol_types.end() || !it->second.is_tf1_polymorphic)
    return false;
  size_t k = it->second.type_vars.size();
  if (k == 0) return false;
  std::string suffix = name.substr(sep + 2);
  std::vector<std::string> segs;
  size_t p = 0;
  for (;;) {
    size_t nxt = suffix.find("__", p);
    if (nxt == std::string::npos) { segs.push_back(suffix.substr(p)); break; }
    segs.push_back(suffix.substr(p, nxt - p));
    p = nxt + 2;
  }
  if (segs.size() != k) return false;
  for (size_t i = 0; i < segs.size(); i++)
    if (segs[i].empty()) return false;  
  out_base = base;
  out_type_args = segs;
  return true;
}
























static void demangle_tff1_recursive(Node *n, NodePool &pool) {
  if (!n) return;
  if (n->kind == NK_FUNC) {
    std::string base;
    std::vector<std::string> type_args;
    if (try_demangle_tff1_name(n->name, base, type_args)) {
      n->name = base;
      std::vector<Node *> new_children;
      for (size_t i = 0; i < type_args.size(); i++) {
        Node *targ = pool.alloc(NK_FUNC);
        targ->name = type_args[i];
        new_children.push_back(targ);
      }
      for (size_t i = 0; i < n->children.size(); i++)
        new_children.push_back(n->children[i]);
      n->children = new_children;
    }
  }
  for (size_t i = 0; i < n->children.size(); i++)
    demangle_tff1_recursive(n->children[i], pool);
}
















static bool strip_sort_guards(Node *n, NodePool &pool) {
  if (!n || (n->kind != NK_FORALL && n->kind != NK_EXISTS) ||
      n->children.empty() || !n->children[0])
    return false;
  bool is_forall = (n->kind == NK_FORALL);
  Node *body = n->children[0];

  std::vector<const Node *> guard_atoms;
  Node *inner;
  if (is_forall) {
    if (body->kind != NK_IMPL || body->children.size() != 2) return false;
    flatten_and_leaves(body->children[0], guard_atoms);
    inner = body->children[1];
  } else {
    if (body->kind != NK_AND) return false;
    std::vector<const Node *> conjuncts;
    flatten_and_leaves(body, conjuncts);
    std::vector<Node *> non_guards;
    for (size_t i = 0; i < conjuncts.size(); i++) {
      std::string v, s;
      if (match_guard_atom(conjuncts[i], v, s))
        guard_atoms.push_back(conjuncts[i]);
      else
        non_guards.push_back(const_cast<Node *>(conjuncts[i]));
    }
    if (non_guards.empty()) return false;  
    














    if (non_guards.size() == 1) {
      inner = non_guards[0];
    } else {
      Node *rebuilt = pool.alloc(NK_AND);
      rebuilt->children = non_guards;
      inner = rebuilt;
    }
  }
  if (guard_atoms.empty()) return false;

  std::map<std::string, std::string> restore;  
  for (size_t i = 0; i < guard_atoms.size(); i++) {
    std::string v, s;
    if (!match_guard_atom(guard_atoms[i], v, s)) return false;
    if (restore.count(v)) return false;  
    restore[v] = s;
  }
  for (std::map<std::string, std::string>::iterator ri = restore.begin();
       ri != restore.end(); ++ri) {
    bool found = false;
    for (size_t vi = 0; vi < n->bound_vars.size(); vi++) {
      if (n->bound_vars[vi] == ri->first) {
        found = true;
        










        if (vi >= n->bound_sorts.size() ||
            (n->bound_sorts[vi] != "$i" && !n->bound_sorts[vi].empty()))
          return false;
        break;
      }
    }
    if (!found) return false;
  }

  for (size_t vi = 0; vi < n->bound_vars.size(); vi++) {
    std::map<std::string, std::string>::iterator ri =
        restore.find(n->bound_vars[vi]);
    if (ri != restore.end()) n->bound_sorts[vi] = ri->second;
  }
  n->children[0] = inner;
  return true;
}




static void strip_sort_guards_recursive(Node *n, NodePool &pool) {
  if (!n) return;
  if (n->kind == NK_FORALL || n->kind == NK_EXISTS)
    strip_sort_guards(n, pool);
  for (size_t i = 0; i < n->children.size(); i++)
    strip_sort_guards_recursive(n->children[i], pool);
}





















static bool is_licensed_sort_closure_fact(const std::string &name,
                                           const std::string &body) {
  static const std::string name_prefix = "lamp_sort_closure_";
  if (name.size() <= name_prefix.size() ||
      name.compare(0, name_prefix.size(), name_prefix) != 0)
    return false;

  NodePool pool;
  Node *ast = NULL;
  try { ast = FormulaParser(body.c_str(), body.size(), pool).parse(); }
  catch (PoolExhausted &) { return false; }
  if (!ast) return false;
  






  demangle_tff1_recursive(ast, pool);

  const Node *n = ast;
  std::set<std::string> bound;
  if (n->kind == NK_FORALL) {
    for (size_t i = 0; i < n->bound_vars.size(); i++) bound.insert(n->bound_vars[i]);
    if (n->children.empty() || !n->children[0]) return false;
    n = n->children[0];
  }
  const Node *concl = n;
  if (n->kind == NK_IMPL) {
    if (n->children.size() != 2) return false;
    std::vector<const Node *> ants;
    flatten_and_leaves(n->children[0], ants);
    for (size_t i = 0; i < ants.size(); i++) {
      std::string v, s;
      if (!match_guard_atom(ants[i], v, s) || !bound.count(v)) return false;
    }
    concl = n->children[1];
  }

  static const std::string guard_prefix = "lamp_sort_";
  if (!concl || concl->kind != NK_PRED || concl->children.size() != 1 ||
      concl->name.size() <= guard_prefix.size() ||
      concl->name.compare(0, guard_prefix.size(), guard_prefix) != 0)
    return false;
  const Node *arg = concl->children[0];
  if (arg->kind == NK_VAR) {
    return bound.empty() || bound.count(arg->name) != 0;
  }
  if (arg->kind == NK_FUNC) {
    if (!Problem_symbols.count(arg->name)) return false;
    for (size_t i = 0; i < arg->children.size(); i++) {
      if (arg->children[i]->kind == NK_VAR && !bound.count(arg->children[i]->name))
        return false;
    }
    return true;
  }
  return false;
}












static bool has_top_level_self_neq(const Node *n, bool negated) {
  if (!n) return false;
  
  if (!negated && n->kind == NK_NEQ && n->children.size() == 2 &&
      node_to_string(n->children[0]) == node_to_string(n->children[1]))
    return true;
  if (!negated && n->kind == NK_NOT && !n->children.empty() &&
      n->children[0]->kind == NK_EQ && n->children[0]->children.size() == 2 &&
      node_to_string(n->children[0]->children[0]) ==
      node_to_string(n->children[0]->children[1]))
    return true;
  
  if (!negated && n->kind == NK_FORALL && !n->children.empty())
    return has_top_level_self_neq(n->children[0], negated);
  
  if (!negated && n->kind == NK_AND) {
    for (size_t i = 0; i < n->children.size(); i++)
      if (has_top_level_self_neq(n->children[i], false)) return true;
    return false;
  }
  
  if (n->kind == NK_NOT && !n->children.empty())
    return has_top_level_self_neq(n->children[0], !negated);
  


  return false;
}

static bool has_self_neq(const Node *n) {
  return has_top_level_self_neq(n, false);
}





static Node *to_nnf(const Node *n, NodePool &pool, bool negated) {
  if (!n) return NULL;

  switch (n->kind) {
    case NK_TRUE:
      return pool.alloc(negated ? NK_FALSE : NK_TRUE);
    case NK_FALSE:
      return pool.alloc(negated ? NK_TRUE : NK_FALSE);

    case NK_NOT:
      return to_nnf(n->children[0], pool, !negated);

    case NK_AND: {
      
      NodeKind k = negated ? NK_OR : NK_AND;
      Node *r = pool.alloc(k);
      for (size_t i = 0; i < n->children.size(); i++)
        r->children.push_back(to_nnf(n->children[i], pool, negated));
      return r;
    }
    case NK_OR: {
      
      NodeKind k = negated ? NK_AND : NK_OR;
      Node *r = pool.alloc(k);
      for (size_t i = 0; i < n->children.size(); i++)
        r->children.push_back(to_nnf(n->children[i], pool, negated));
      return r;
    }

    case NK_IMPL: {
      
      if (negated) {
        Node *r = pool.alloc(NK_AND);
        r->children.push_back(to_nnf(n->children[0], pool, false));
        r->children.push_back(to_nnf(n->children[1], pool, true));
        return r;
      }
      Node *r = pool.alloc(NK_OR);
      r->children.push_back(to_nnf(n->children[0], pool, true));
      r->children.push_back(to_nnf(n->children[1], pool, false));
      return r;
    }

    case NK_IFF: {
      

      if (negated) {
        
        Node *r = pool.alloc(NK_AND);
        Node *c1 = pool.alloc(NK_OR);
        c1->children.push_back(to_nnf(n->children[0], pool, true));
        c1->children.push_back(to_nnf(n->children[1], pool, true));
        Node *c2 = pool.alloc(NK_OR);
        c2->children.push_back(to_nnf(n->children[0], pool, false));
        c2->children.push_back(to_nnf(n->children[1], pool, false));
        r->children.push_back(c1);
        r->children.push_back(c2);
        return r;
      }
      Node *r = pool.alloc(NK_AND);
      Node *c1 = pool.alloc(NK_OR);
      c1->children.push_back(to_nnf(n->children[0], pool, true));
      c1->children.push_back(to_nnf(n->children[1], pool, false));
      Node *c2 = pool.alloc(NK_OR);
      c2->children.push_back(to_nnf(n->children[0], pool, false));
      c2->children.push_back(to_nnf(n->children[1], pool, true));
      r->children.push_back(c1);
      r->children.push_back(c2);
      return r;
    }

    case NK_XOR: {
      
      if (negated) {
        
        Node *r = pool.alloc(NK_AND);
        Node *c1 = pool.alloc(NK_OR);
        c1->children.push_back(to_nnf(n->children[0], pool, true));
        c1->children.push_back(to_nnf(n->children[1], pool, false));
        Node *c2 = pool.alloc(NK_OR);
        c2->children.push_back(to_nnf(n->children[0], pool, false));
        c2->children.push_back(to_nnf(n->children[1], pool, true));
        r->children.push_back(c1);
        r->children.push_back(c2);
        return r;
      }
      Node *r = pool.alloc(NK_AND);
      Node *c1 = pool.alloc(NK_OR);
      c1->children.push_back(to_nnf(n->children[0], pool, false));
      c1->children.push_back(to_nnf(n->children[1], pool, false));
      Node *c2 = pool.alloc(NK_OR);
      c2->children.push_back(to_nnf(n->children[0], pool, true));
      c2->children.push_back(to_nnf(n->children[1], pool, true));
      r->children.push_back(c1);
      r->children.push_back(c2);
      return r;
    }

    case NK_FORALL:
    case NK_EXISTS: {
      
      NodeKind k = n->kind;
      if (negated)
        k = (k == NK_FORALL) ? NK_EXISTS : NK_FORALL;
      Node *r = pool.alloc(k);
      r->bound_vars = n->bound_vars;
      r->bound_sorts = n->bound_sorts;
      r->children.push_back(to_nnf(n->children[0], pool, negated));
      return r;
    }

    case NK_EQ:
    case NK_NEQ: {
      NodeKind k = n->kind;
      if (negated) k = (k == NK_EQ) ? NK_NEQ : NK_EQ;
      Node *r = pool.alloc(k);
      r->children.push_back(ast_clone(n->children[0], pool));
      r->children.push_back(ast_clone(n->children[1], pool));
      return r;
    }

    default: {
      
      if (negated) {
        Node *r = pool.alloc(NK_NOT);
        r->children.push_back(ast_clone(n, pool));
        return r;
      }
      return ast_clone(n, pool);
    }
  }
}




static void ast_flatten(Node *n) {
  if (!n) return;
  for (size_t i = 0; i < n->children.size(); i++)
    ast_flatten(n->children[i]);

  if (n->kind != NK_AND && n->kind != NK_OR) return;
  std::vector<Node *> flat;
  for (size_t i = 0; i < n->children.size(); i++) {
    if (n->children[i]->kind == n->kind) {
      for (size_t j = 0; j < n->children[i]->children.size(); j++)
        flat.push_back(n->children[i]->children[j]);
    } else {
      flat.push_back(n->children[i]);
    }
  }
  n->children = flat;
}














static void collect_lit_sigs(const Node *n, bool negated,
                              std::set<std::pair<std::string, bool> > &out) {
  if (!n) return;
  if (n->kind == NK_NOT) {
    if (n->children.size() == 1)
      collect_lit_sigs(n->children[0], !negated, out);
    return;
  }
  if (n->kind == NK_PRED) {
    out.insert(std::make_pair(n->name, !negated));
    return;
  }
  if (n->kind == NK_EQ) {
    out.insert(std::make_pair(std::string("="), !negated));
    return;
  }
  if (n->kind == NK_NEQ) {
    out.insert(std::make_pair(std::string("="), negated));
    return;
  }
  if (n->kind == NK_TRUE || n->kind == NK_FALSE) return;
  for (size_t i = 0; i < n->children.size(); i++)
    collect_lit_sigs(n->children[i], negated, out);
}






static bool is_skolem_term_name(const std::string &name) {
  if (name.empty()) return false;
  
  if (name.size() > 3 && name.compare(0, 3, "esk") == 0) {
    bool ok = true;
    for (size_t i = 3; i < name.size(); i++)
      if (!isdigit((unsigned char)name[i]) && name[i] != '_') { ok = false; break; }
    if (ok) return true;
  }
  
  if (name.size() > 2 && (name.compare(0, 2, "sK") == 0 ||
                          name.compare(0, 2, "sF") == 0)) {
    bool ok = true;
    for (size_t i = 2; i < name.size(); i++)
      if (!isdigit((unsigned char)name[i])) { ok = false; break; }
    if (ok) return true;
  }
  
  if (name.size() > 1 && (name[0] == 'c' || name[0] == 'f')) {
    bool ok = true;
    for (size_t i = 1; i < name.size(); i++)
      if (!isdigit((unsigned char)name[i])) { ok = false; break; }
    if (ok) return true;
  }
  return false;
}










static void canonical_shape_walk(const Node *n,
                                 std::map<std::string, std::string> &var_map,
                                 std::map<std::string, std::string> &sk_map,
                                 std::map<std::string, std::string> &ep_map,
                                 std::string &out);
static void canonical_shape_walk(const Node *n,
                                 std::map<std::string, std::string> &var_map,
                                 std::map<std::string, std::string> &sk_map,
                                 std::map<std::string, std::string> &ep_map,
                                 std::string &out) {
  if (!n) { out += "<null>"; return; }
  switch (n->kind) {
    case NK_VAR: {
      std::map<std::string, std::string>::iterator it = var_map.find(n->name);
      if (it == var_map.end()) {
        char buf[16];
        snprintf(buf, sizeof(buf), "V%zu", var_map.size());
        var_map[n->name] = buf;
        out += buf;
      } else {
        out += it->second;
      }
      return;
    }
    case NK_FUNC: {
      std::string nm = n->name;
      if (is_skolem_term_name(nm)) {
        std::map<std::string, std::string>::iterator it = sk_map.find(nm);
        if (it == sk_map.end()) {
          char buf[16];
          snprintf(buf, sizeof(buf), "SK%zu", sk_map.size());
          sk_map[nm] = buf;
          out += buf;
        } else {
          out += it->second;
        }
      } else {
        out += nm;
      }
      if (!n->children.empty()) {
        out += '(';
        for (size_t i = 0; i < n->children.size(); i++) {
          if (i) out += ',';
          canonical_shape_walk(n->children[i], var_map, sk_map, ep_map, out);
        }
        out += ')';
      }
      return;
    }
    case NK_PRED: {
      std::string nm = n->name;
      bool is_ep = false;
      if (nm.size() > 5 && nm.compare(0, 5, "epred") == 0) {
        size_t i = 5;
        while (i < nm.size() && (isdigit((unsigned char)nm[i]) || nm[i] == '_')) i++;
        if (i == nm.size()) is_ep = true;
      }
      if (is_ep) {
        std::map<std::string, std::string>::iterator it = ep_map.find(nm);
        if (it == ep_map.end()) {
          char buf[16];
          snprintf(buf, sizeof(buf), "EP%zu", ep_map.size());
          ep_map[nm] = buf;
          out += buf;
        } else {
          out += it->second;
        }
      } else {
        out += nm;
      }
      if (!n->children.empty()) {
        out += '(';
        for (size_t i = 0; i < n->children.size(); i++) {
          if (i) out += ',';
          canonical_shape_walk(n->children[i], var_map, sk_map, ep_map, out);
        }
        out += ')';
      }
      return;
    }
    case NK_NOT:
      out += '~';
      if (!n->children.empty())
        canonical_shape_walk(n->children[0], var_map, sk_map, ep_map, out);
      return;
    case NK_OR: {
      



      

      std::vector<const Node *> flat_children;
      {
        std::vector<const Node *> q;
        q.push_back(n);
        for (size_t qi = 0; qi < q.size(); qi++) {
          const Node *cur = q[qi];
          if (!cur) continue;
          if (cur->kind == NK_OR) {
            for (size_t i = 0; i < cur->children.size(); i++)
              q.push_back(cur->children[i]);
          } else {
            flat_children.push_back(cur);
          }
        }
      }
      std::vector<std::string> parts;
      for (size_t i = 0; i < flat_children.size(); i++) {
        std::string p;
        canonical_shape_walk(flat_children[i], var_map, sk_map, ep_map, p);
        parts.push_back(p);
      }
      std::sort(parts.begin(), parts.end());
      out += '(';
      for (size_t i = 0; i < parts.size(); i++) {
        if (i) out += '|';
        out += parts[i];
      }
      out += ')';
      return;
    }
    case NK_EQ:
    case NK_NEQ: {
      
      std::string a, b;
      if (n->children.size() == 2) {
        canonical_shape_walk(n->children[0], var_map, sk_map, ep_map, a);
        canonical_shape_walk(n->children[1], var_map, sk_map, ep_map, b);
      }
      if (b < a) { std::string t = a; a = b; b = t; }
      out += a;
      out += (n->kind == NK_EQ) ? "=" : "!=";
      out += b;
      return;
    }
    case NK_TRUE:  out += "$true"; return;
    case NK_FALSE: out += "$false"; return;
    case NK_NUMBER: out += n->name; return;
    default:
      out += "<?>";
      for (size_t i = 0; i < n->children.size(); i++) {
        out += ',';
        canonical_shape_walk(n->children[i], var_map, sk_map, ep_map, out);
      }
      return;
  }
}

static std::string canonical_clause_shape(const Node *n) {
  std::map<std::string, std::string> var_map, sk_map, ep_map;
  std::string out;
  canonical_shape_walk(n, var_map, sk_map, ep_map, out);
  return out;
}








static bool is_epred_name(const std::string &name) {
  if (name.length() < 7) return false;
  if (name.substr(0, 5) != "epred") return false;
  size_t i = 5;
  if (i >= name.length() || !isdigit((unsigned char)name[i])) return false;
  while (i < name.length() && isdigit((unsigned char)name[i])) i++;
  if (i >= name.length() || name[i] != '_') return false;
  i++;
  if (i >= name.length() || !isdigit((unsigned char)name[i])) return false;
  while (i < name.length() && isdigit((unsigned char)name[i])) i++;
  return i == name.length();
}




static bool ast_syntactic_equal(const Node *a, const Node *b) {
  if (!a || !b) return a == b;
  if (a->kind != b->kind) return false;
  if (a->name != b->name) return false;
  if (a->bound_vars != b->bound_vars) return false;
  if (a->children.size() != b->children.size()) return false;
  for (size_t i = 0; i < a->children.size(); i++)
    if (!ast_syntactic_equal(a->children[i], b->children[i])) return false;
  return true;
}
















static void collect_lit_sigs_multiset(
    const Node *n, bool negated,
    std::map<std::pair<std::string, bool>, int> &out) {
  if (!n) return;
  if (n->kind == NK_NOT) {
    if (n->children.size() == 1)
      collect_lit_sigs_multiset(n->children[0], !negated, out);
    return;
  }
  if (n->kind == NK_PRED) {
    std::string name = is_epred_name(n->name) ? "_EPRED_" : n->name;
    out[std::make_pair(name, !negated)]++;
    return;
  }
  if (n->kind == NK_EQ) {
    
    if (n->children.size() == 2 &&
        ast_syntactic_equal(n->children[0], n->children[1]))
      return;
    out[std::make_pair(std::string("="), !negated)]++;
    return;
  }
  if (n->kind == NK_NEQ) {
    
    if (n->children.size() == 2 &&
        ast_syntactic_equal(n->children[0], n->children[1]))
      return;
    out[std::make_pair(std::string("="), negated)]++;
    return;
  }
  if (n->kind == NK_TRUE || n->kind == NK_FALSE) return;
  for (size_t i = 0; i < n->children.size(); i++)
    collect_lit_sigs_multiset(n->children[i], negated, out);
}


static Node *merge_quantifiers(Node *n, NodePool &pool) {
  if (!n) return NULL;
  for (size_t i = 0; i < n->children.size(); i++)
    n->children[i] = merge_quantifiers(n->children[i], pool);

  if ((n->kind == NK_FORALL || n->kind == NK_EXISTS) &&
      !n->children.empty() && n->children[0]->kind == n->kind) {
    Node *inner = n->children[0];
    for (size_t i = 0; i < inner->bound_vars.size(); i++)
      n->bound_vars.push_back(inner->bound_vars[i]);
    n->children[0] = inner->children[0];
    return merge_quantifiers(n, pool);  
  }
  return n;
}


static Node *remove_vacuous(Node *n) {
  if (!n) return NULL;
  for (size_t i = 0; i < n->children.size(); i++)
    n->children[i] = remove_vacuous(n->children[i]);

  if (n->kind != NK_FORALL && n->kind != NK_EXISTS) return n;
  if (n->children.empty()) return n;

  std::set<std::string> fv = free_vars(n->children[0]);
  std::vector<std::string> kept;
  for (size_t i = 0; i < n->bound_vars.size(); i++)
    if (fv.count(n->bound_vars[i])) kept.push_back(n->bound_vars[i]);
  if (kept.empty()) return n->children[0];
  n->bound_vars = kept;
  return n;
}












































































