      const ProofStep &step = it->second;
      if (step.rule != "split_conjunct") continue;
      std::string canon;
      try {
        NodePool spool;
        Node *sast = FormulaParser(step.body.c_str(), step.body.size(), spool).parse();
        if (sast) {
          Node *sc = fof_canonicalize(sast, spool);
          if (sc) canon = node_to_string(sc);
        }
      } catch (PoolExhausted &) {}
      if (canon.empty()) canon = normalize_ws(step.body);  
      for (size_t pi = 0; pi < step.parents.size(); pi++)
        split_bodies[step.parents[pi]].insert(canon);
