  auto strip_leading_forall = [](std::string s) -> std::string {
    for (;;) {
      strim(s);
      if (s.size() >= 2 && s.front() == '(' && s.back() == ')') {
        int d = 0; bool whole = true;
        for (size_t j = 0; j < s.size(); j++) {
          if (s[j] == '(') d++;
          else if (s[j] == ')') { d--; if (d == 0 && j != s.size() - 1) { whole = false; break; } }
        }
        if (whole) { s = s.substr(1, s.size() - 2); continue; }
      }
      if (s.empty() || s[0] != '!') return s;
      size_t p = 1;
      while (p < s.size() && isspace((unsigned char)s[p])) p++;
      if (p >= s.size() || s[p] != '[') return s;
      int d = 0; size_t j = p;
      for (; j < s.size(); j++) {
        if (s[j] == '[') d++;
        else if (s[j] == ']') { d--; if (d == 0) { j++; break; } }
      }
      if (d != 0) return s;  
      while (j < s.size() && isspace((unsigned char)s[j])) j++;
      if (j >= s.size() || s[j] != ':') return s;
      s = s.substr(j + 1);
      

    }
  };

  













  std::map<std::string, std::string> avatar_defs;  
  for (std::map<std::string, ProofStep>::iterator it = clauses.begin();
       it != clauses.end(); ++it) {
    const ProofStep &s = it->second;
    if (!s.is_introduced || s.rule != "avatar_definition") continue;
    




    std::string b = strip_leading_forall(s.body);
    int d = 0;
    size_t iff = std::string::npos;
    for (size_t j = 0; j + 2 < b.size(); j++) {
      char ch = b[j];
      if (ch == '(' || ch == '[') d++;
      else if (ch == ')' || ch == ']') d--;
      else if (d == 0 && ch == '<' && b[j+1] == '=' && b[j+2] == '>') {
        iff = j; break;
      }
    }
    if (iff == std::string::npos) continue;
    std::string lhs = b.substr(0, iff);
    std::string rhs = b.substr(iff + 3);
    strim(lhs); strim(rhs);
    
    if (lhs.size() >= 2 && lhs.front() == '(' && lhs.back() == ')')
      lhs = lhs.substr(1, lhs.size() - 2), strim(lhs);
    if (rhs.size() >= 2 && rhs.front() == '(' && rhs.back() == ')')
      rhs = rhs.substr(1, rhs.size() - 2), strim(rhs);
    



    rhs = strip_leading_forall(rhs);
    avatar_defs[lhs] = rhs;
  }

  




  
  auto avatar_norm = [](std::string s) -> std::string {
    s = normalize_ws(s);
    while (s.size() >= 2 && s.front() == '(' && s.back() == ')') {
      int d = 0; bool ok = true;
      for (size_t j = 0; j < s.size(); j++) {
        if (s[j] == '(') d++;
        else if (s[j] == ')') { d--; if (d == 0 && j != s.size()-1) { ok = false; break; } }
      }
      if (!ok) break;
      s = s.substr(1, s.size() - 2);
      s = normalize_ws(s);
    }
    return s;
  };

  
  auto split_clause_lits = [](const std::string &body) -> std::vector<std::string> {
    std::vector<std::string> out;
    int d = 0;
    size_t start = 0;
    for (size_t j = 0; j <= body.size(); j++) {
      char c = (j < body.size()) ? body[j] : '|';
      if (c == '(' || c == '[') d++;
      else if (c == ')' || c == ']') d--;
      else if (c == '|' && d == 0) {
        std::string lit = body.substr(start, j - start);
        strim(lit);
        if (!lit.empty()) out.push_back(lit);
        start = j + 1;
      }
    }
    return out;
  };

  
  auto negate_lit = [](const std::string &lit) -> std::string {
    std::string l = lit;
    strim(l);
    
    while (l.size() >= 2 && l.front() == '(' && l.back() == ')') {
      int d = 0; bool ok = true;
      for (size_t j = 0; j < l.size(); j++) {
        if (l[j] == '(') d++;
        else if (l[j] == ')') { d--; if (d == 0 && j != l.size()-1) { ok = false; break; } }
      }
      if (!ok) break;
      l = l.substr(1, l.size() - 2);
      strim(l);
    }
    if (!l.empty() && l[0] == '~') {
      std::string r = l.substr(1);
      strim(r);
      return r;
    }
    
    int d = 0;
    for (size_t j = 0; j + 1 < l.size(); j++) {
      if (l[j] == '(' || l[j] == '[') d++;
      else if (l[j] == ')' || l[j] == ']') d--;
      else if (d == 0 && l[j] == '!' && l[j+1] == '=') {
        return l.substr(0, j) + "=" + l.substr(j + 2);
      }
      else if (d == 0 && l[j] == '=' && (j == 0 || l[j-1] != '!') &&
               (j + 1 >= l.size() || l[j+1] != '>')) {
        return l.substr(0, j) + "!=" + l.substr(j + 1);
      }
    }
    return "~" + l;
  };

  
  auto lits_set_eq = [&](std::vector<std::string> a, std::vector<std::string> b) -> bool {
    if (a.size() != b.size()) return false;
    for (auto &x : a) x = avatar_norm(x);
    for (auto &x : b) x = avatar_norm(x);
    std::sort(a.begin(), a.end());
    std::sort(b.begin(), b.end());
    return a == b;
  };

  


  auto verify_avatar_component_clause = [&](const ProofStep &step,
                                             const std::map<std::string, ProofStep> &cls) -> bool {
    if (step.parents.size() != 1) return false;
    auto pit = cls.find(step.parents[0]);
    if (pit == cls.end()) return false;
    if (!pit->second.is_introduced || pit->second.rule != "avatar_definition")
      return false;
    
    


    std::string pb = strip_leading_forall(pit->second.body);
    int d = 0;
    size_t iff = std::string::npos;
    for (size_t j = 0; j + 2 < pb.size(); j++) {
      char ch = pb[j];
      if (ch == '(' || ch == '[') d++;
      else if (ch == ')' || ch == ']') d--;
      else if (d == 0 && ch == '<' && pb[j+1] == '=' && pb[j+2] == '>') {
        iff = j; break;
      }
    }
    if (iff == std::string::npos) return false;
    std::string spl_n = pb.substr(0, iff); strim(spl_n);
    while (spl_n.size() >= 2 && spl_n.front() == '(' && spl_n.back() == ')')
      spl_n = spl_n.substr(1, spl_n.size() - 2), strim(spl_n);
    std::string body_def = pb.substr(iff + 3); strim(body_def);
    while (body_def.size() >= 2 && body_def.front() == '(' && body_def.back() == ')')
      body_def = body_def.substr(1, body_def.size() - 2), strim(body_def);
    


    body_def = strip_leading_forall(body_def);

    
    std::vector<std::string> concl_lits = split_clause_lits(step.body);

    

    std::vector<std::string> body_lits = split_clause_lits(body_def);

    


    std::vector<std::string> form_a, form_b;
    for (auto &l : body_lits) form_a.push_back(negate_lit(l));
    form_a.push_back(spl_n);
    for (auto &l : body_lits) form_b.push_back(l);
    form_b.push_back(negate_lit(spl_n));

    return lits_set_eq(concl_lits, form_a) || lits_set_eq(concl_lits, form_b);
  };

  





  auto verify_avatar_split_clause = [&](const ProofStep &step,
                                         const std::map<std::string, ProofStep> &cls) -> bool {
    if (step.parents.size() != 1) return false;
    auto pit = cls.find(step.parents[0]);
    if (pit == cls.end()) return false;
    std::vector<std::string> par_lits = split_clause_lits(pit->second.body);
    std::vector<std::string> con_lits = split_clause_lits(step.body);
    
    for (auto &x : par_lits) x = avatar_norm(x);
    int spl_count = 0;
    for (auto &x : con_lits) {
      x = avatar_norm(x);
      std::string atom = x;
      if (!atom.empty() && atom[0] == '~') { atom = atom.substr(1); strim(atom); }
      if (avatar_defs.count(atom)) { spl_count++; continue; }
      
      bool found = false;
      for (auto &pl : par_lits) if (pl == x) { found = true; break; }
      if (!found) return false;
    }
    return spl_count == 1;
  };

  

  auto verify_avatar_contradiction_clause = [&](const ProofStep &step,
                                                  const std::map<std::string, ProofStep> &cls) -> bool {
    if (step.parents.size() != 1) return false;
    auto pit = cls.find(step.parents[0]);
    if (pit == cls.end()) return false;
    std::vector<std::string> par_lits = split_clause_lits(pit->second.body);
    std::vector<std::string> con_lits = split_clause_lits(step.body);
    
    std::vector<std::string> filtered;
    for (auto &l : par_lits) {
      std::string n = avatar_norm(l);
      if (n == "$false" || n == "false") continue;
      filtered.push_back(n);
    }
    for (auto &x : con_lits) x = avatar_norm(x);
    return lits_set_eq(filtered, con_lits);
  };

  



  auto verify_avatar_sat_refutation = [&](const ProofStep &step,
                                            const std::map<std::string, ProofStep> &cls) -> bool {
    
    std::string cb = avatar_norm(step.body);
    if (cb != "$false" && cb != "false") return false;
    
    std::map<std::string, int> var_of;
    std::vector<std::vector<int> > sat_clauses;
    for (auto &pn : step.parents) {
      auto pit = cls.find(pn);
      if (pit == cls.end()) return false;
      std::vector<std::string> lits = split_clause_lits(pit->second.body);
      std::vector<int> dimacs;
      for (auto &l : lits) {
        std::string a = avatar_norm(l);
        bool neg = false;
        if (!a.empty() && a[0] == '~') { neg = true; a = a.substr(1); strim(a); }
        
        if (!avatar_defs.count(a)) return false;
        int v = var_of.count(a) ? var_of[a] : (int)(var_of[a] = (int)var_of.size() + 1);
        dimacs.push_back(neg ? -v : v);
      }
      if (dimacs.empty()) return false;
      sat_clauses.push_back(dimacs);
    }
    int nvars = (int)var_of.size();
    std::vector<int> assign(nvars, 0);
    
    return !sidestep::dpll_solve(sat_clauses, assign, nvars);
  };

  








  


  auto verify_canonical_equiv = [&](const ProofStep &step,
                                     const std::map<std::string, ProofStep> &cls) -> bool {
    if (step.parents.size() != 1) return false;
    auto pit = cls.find(step.parents[0]);
    if (pit == cls.end()) return false;
    NodePool ppool;
    Node *pa = NULL, *sa = NULL;
    try {
      pa = FormulaParser(pit->second.body.c_str(),
                          pit->second.body.size(), ppool).parse();
      sa = FormulaParser(step.body.c_str(),
                          step.body.size(), ppool).parse();
    } catch (PoolExhausted &) { return false; }
    if (!pa || !sa) return false;
    
    Node *pl = NULL, *sl = NULL;
    try {
      pl = fof_canonicalize_light(pa, ppool);
      sl = fof_canonicalize_light(sa, ppool);
    } catch (PoolExhausted &) {}
    if (pl && sl && node_to_string(pl) == node_to_string(sl)) return true;
    
    Node *pf = NULL, *sf = NULL;
    try {
      pf = fof_canonicalize(pa, ppool);
      sf = fof_canonicalize(sa, ppool);
    } catch (PoolExhausted &) {}
    if (pf && sf && node_to_string(pf) == node_to_string(sf)) return true;
    




    {
      std::string equiv = "fof(check, conjecture, (("
          + pit->second.body + ") <=> ("
          + step.body + "))).\n";
      if (run_atp_on_problem(equiv, 5)) return true;
    }
    return false;
  };

  








  auto verify_definition_folding = [&](const ProofStep &step,
                                         const std::map<std::string, ProofStep> &cls) -> bool {
    if (step.parents.empty()) return false;
    


    auto p0 = cls.find(step.parents[0]);
    if (p0 == cls.end()) return false;
    {
      NodePool ppool;
      Node *pa = NULL, *sa = NULL;
      try {
        pa = FormulaParser(p0->second.body.c_str(),
                            p0->second.body.size(), ppool).parse();
        sa = FormulaParser(step.body.c_str(),
                            step.body.size(), ppool).parse();
      } catch (PoolExhausted &) {}
      if (pa && sa) {
        Node *pl = NULL, *sl = NULL;
        try {
          pl = fof_canonicalize_light(pa, ppool);
          sl = fof_canonicalize_light(sa, ppool);
        } catch (PoolExhausted &) {}
        if (pl && sl && node_to_string(pl) == node_to_string(sl)) return true;
      }
    }
    
    std::string atp_problem;
    for (size_t i = 1; i < step.parents.size(); i++) {
      auto pi = cls.find(step.parents[i]);
      if (pi == cls.end()) return false;
      atp_problem += "fof(def" + std::to_string(i) + ", axiom, "
                  + pi->second.body + ").\n";
    }
    atp_problem += "fof(check, conjecture, (("
                + p0->second.body + ") <=> ("
                + step.body + "))).\n";
    return run_atp_on_problem(atp_problem, 5);
  };

  if (vtp_prof) { ph_2k_us = ph_now() - ph_t; ph_t = ph_now(); }

  
  long p3_polarity_us = 0;
  long p3_splitconj_us = 0;
  long p3_unroll_us = 0;
  long p3_problem_us = 0;
  long p3_negconj_us = 0;
  long p3_loop_other_us = 0;
  int p3_polarity_n = 0, p3_splitconj_n = 0, p3_unroll_n = 0, p3_negconj_n = 0;

  







