static std::string sha256_hex(const std::string &data) {
  static const uint32_t k[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,
    0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,
    0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,
    0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,
    0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,
    0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,
    0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,
    0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,
    0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
  auto rotr = [](uint32_t x, int n) { return (x >> n) | (x << (32 - n)); };

  uint32_t h[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                    0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};

  std::string msg = data;
  uint64_t bit_len = (uint64_t)data.size() * 8;
  msg.push_back((char)0x80);
  while (msg.size() % 64 != 56) msg.push_back((char)0x00);
  for (int i = 7; i >= 0; i--) msg.push_back((char)((bit_len >> (i * 8)) & 0xff));

  for (size_t chunk = 0; chunk < msg.size(); chunk += 64) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) {
      w[i] = ((uint32_t)(unsigned char)msg[chunk + i * 4] << 24) |
             ((uint32_t)(unsigned char)msg[chunk + i * 4 + 1] << 16) |
             ((uint32_t)(unsigned char)msg[chunk + i * 4 + 2] << 8) |
             ((uint32_t)(unsigned char)msg[chunk + i * 4 + 3]);
    }
    for (int i = 16; i < 64; i++) {
      uint32_t s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >> 3);
      uint32_t s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >> 10);
      w[i] = w[i-16] + s0 + w[i-7] + s1;
    }
    uint32_t a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
    for (int i = 0; i < 64; i++) {
      uint32_t S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      uint32_t ch = (e & f) ^ ((~e) & g);
      uint32_t temp1 = hh + S1 + ch + k[i] + w[i];
      uint32_t S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
      uint32_t temp2 = S0 + maj;
      hh=g; g=f; f=e; e=d+temp1; d=c; c=b; b=a; a=temp1+temp2;
    }
    h[0]+=a; h[1]+=b; h[2]+=c; h[3]+=d; h[4]+=e; h[5]+=f; h[6]+=g; h[7]+=hh;
  }

  char out[65];
  for (int i = 0; i < 8; i++) snprintf(out + i * 8, 9, "%08x", h[i]);
  return std::string(out, 64);
}







static const char *Expected_license_sha256 =
  "137fe158f7abcc2c6dd51c5ffa68782eb628e444e2e98fc6eb531ed28d1027ae";

static void check_license_integrity() {
  




  static const char *empty_sha256 =
    "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
  static const char *abc_sha256 =
    "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad";
  if (sha256_hex("") != empty_sha256 || sha256_hex("abc") != abc_sha256) {
    fprintf(stderr, "proofcheck: internal error, SHA-256 self-test failed -- "
                    "refusing to run a license check it cannot trust.\n");
    emit_status("%% SZS status Unknown : internal SHA-256 self-test failed\n");
    exit(1);
  }

  if (Exe_dir.empty()) {
    fprintf(stderr, "proofcheck: cannot resolve my own executable "
                    "directory, so cannot locate LICENSE.  Refusing to "
                    "run without confirming the license is present and "
                    "unaltered.\n");
    emit_status("%% SZS status Unknown : cannot locate LICENSE (exe dir unresolved)\n");
    exit(1);
  }

  std::string license_path = Exe_dir + "/LICENSE";
  FILE *lf = fopen(license_path.c_str(), "rb");
  if (!lf) {
    fprintf(stderr, "proofcheck: LICENSE not found at '%s'.  This binary "
                    "must not be run without the license that governs it "
                    "distributed alongside it.\n", license_path.c_str());
    emit_status("%% SZS status Unknown : LICENSE file missing\n");
    exit(1);
  }
  std::string content;
  char buf[65536];
  size_t nr;
  while ((nr = fread(buf, 1, sizeof(buf), lf)) > 0)
    content.append(buf, nr);
  fclose(lf);

  std::string actual = sha256_hex(content);
  if (actual != Expected_license_sha256) {
    fprintf(stderr, "proofcheck: LICENSE at '%s' does not match the "
                    "expected text (sha256 %s, expected %s).  Refusing to "
                    "run next to an altered license.\n",
                    license_path.c_str(), actual.c_str(),
                    Expected_license_sha256);
    emit_status("%% SZS status Unknown : LICENSE file altered\n");
    exit(1);
  }
}



int main(int argc, char *argv[]) {
  












  signal(SIGPIPE, SIG_IGN);

  

  if (argc > 0 && argv[0]) {
    char resolved[4096];
    if (strchr(argv[0], '/')) {
      if (realpath(argv[0], resolved)) {
        char *slash = strrchr(resolved, '/');
        if (slash) { *slash = '\0'; Exe_dir = resolved; }
      }
    } else {
      
      std::string found = find_executable(argv[0]);
      if (!found.empty() && realpath(found.c_str(), resolved)) {
        char *slash = strrchr(resolved, '/');
        if (slash) { *slash = '\0'; Exe_dir = resolved; }
      }
    }
  }

  


  check_license_integrity();

  for (int i = 1; i < argc; i++) {
    if (strcmp(argv[i], "-self-certify") == 0 ||
        strcmp(argv[i], "--self-certify") == 0) {
      return run_self_certify();
    }
  }

  install_signal_handlers();

  


  int max_children = 8;
  int timeout_sec = 5;
  int timeout_user_set = 0;
  int wall_timeout = 28;  















  int assurance_level = 0;  
  const int strict = 1;  
  int verbose = 1; 
  const char *input_file = NULL;
  const char *problem_file = NULL;
  const char *model_file = NULL;

  
  for (int i = 1; i < argc; i++) {
    if (strcmp(argv[i], "-j") == 0 && i + 1 < argc) {
      max_children = atoi(argv[++i]);
      if (max_children < 1) max_children = 1;
    } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
      timeout_sec = atoi(argv[++i]);
      if (timeout_sec < 1) timeout_sec = 1;
      timeout_user_set = 1;
    } else if (strcmp(argv[i], "-p") == 0 && i + 1 < argc) {
      problem_file = argv[++i];
    } else if (strcmp(argv[i], "-m") == 0 && i + 1 < argc) {
      model_file = argv[++i];
    } else if (strcmp(argv[i], "-e") == 0 && i + 1 < argc) {
      Atp_command = argv[++i];  
    } else if (strcmp(argv[i], "-aa") == 0) {
      assurance_level = 2;
    } else if (strcmp(argv[i], "-a") == 0 || strcmp(argv[i], "--assurance") == 0) {
      assurance_level = 1;
    } else if (strcmp(argv[i], "-T") == 0 && i + 1 < argc) {
      wall_timeout = atoi(argv[++i]);
      if (wall_timeout < 1) wall_timeout = 1;
    } else if (strcmp(argv[i], "-fail_fast") == 0) {
      


      Fail_fast_mode = true;
    } else if (strcmp(argv[i], "-audit-sidestep") == 0) {
      Audit_sidestep = 1;
    } else if (strcmp(argv[i], "-sidestep-audit") == 0 && i + 1 < argc) {
      Sidestep_audit = 1;
      Sidestep_audit_path = argv[++i];
    } else if (strcmp(argv[i], "-v") == 0) {
      verbose = 1;  
    } else if (strcmp(argv[i], "-quiet") == 0) {
      verbose = 0;
    } else if (argv[i][0] != '-') {
      input_file = argv[i];
    } else {
      usage();
    }
  }

  



  if (!verbose) {
    int nfd = open("/dev/null", O_WRONLY);
    if (nfd >= 0) { dup2(nfd, STDERR_FILENO); close(nfd); }
  }

  
  if (input_file) Current_proof_name = input_file;

  



  if (Sidestep_audit) {
    Sidestep_audit_fp = fopen(Sidestep_audit_path.c_str(), "a");
    if (!Sidestep_audit_fp) {
      fprintf(stderr, "proofcheck: cannot open audit file '%s': %s\n",
              Sidestep_audit_path.c_str(), strerror(errno));
      exit(1);
    }
    
    fseek(Sidestep_audit_fp, 0, SEEK_END);
    if (ftell(Sidestep_audit_fp) == 0) {
      fprintf(Sidestep_audit_fp,
              "proof\tstep\trule\tss_result\tatp_result\n");
    }
    if (!timeout_user_set) timeout_sec = 10;
    fprintf(stderr, "Sidestep audit: logging to %s (per-step timeout %ds)\n",
            Sidestep_audit_path.c_str(), timeout_sec);
    atexit(sidestep_audit_dump_summary);
  }

  








  
  if (wall_timeout > 0) {
    alarm(wall_timeout);
    fprintf(stderr, "Wall-clock timeout: %ds\n", wall_timeout);
  }

  banner();

  






  if (Atp_command.empty()) {
    if (!auto_discover_atp()) {
      fprintf(stderr,
              "proofcheck: eprover not found.  eprover is mandatory for "
              "per-step entailment and the cnf-check defense.  Place it "
              "alongside proofcheck (%s/eprover) or in PATH, or specify -e.\n",
              Exe_dir.empty() ? "<exe-dir>" : Exe_dir.c_str());
      


      emit_status("%% SZS status Unknown : eprover backend not found\n");
      return 1;
    }
  } else {
    
    if (!resolve_atp(Atp_command) ||
        !is_executable_file(Atp_command.c_str())) {
      fprintf(stderr,
              "proofcheck: -e '%s' is not an executable file.  eprover is "
              "mandatory; specify a valid path or omit -e to auto-discover.\n",
              Atp_command.c_str());
      emit_status("%% SZS status Unknown : eprover backend not executable\n");
      return 1;
    }
  }
  fprintf(stderr, "ATP backend: %s\n", Atp_command.c_str());
  Entailment_command = Atp_command;  

  








  {
    std::string m;
    if (!Exe_dir.empty()) {
      std::string me = Exe_dir + "/mace4";
      if (is_executable_file(me.c_str())) m = me;
    }
    if (m.empty()) m = find_executable("mace4");
    if (m.empty()) {
      fprintf(stderr,
              "proofcheck: mace4 not found.  mace4 is mandatory for "
              "countermodel-based disproof.  Place it alongside proofcheck "
              "(%s/mace4) or in PATH.\n",
              Exe_dir.empty() ? "<exe-dir>" : Exe_dir.c_str());
      
      emit_status("%% SZS status Unknown : mace4 backend not found\n");
      return 1;
    }
    Mace4_command = m;
    fprintf(stderr, "Countermodel finder: %s\n", m.c_str());
  }

  






  {
    std::string p;
    if (!Exe_dir.empty()) {
      std::string pe = Exe_dir + "/prover9";
      if (is_executable_file(pe.c_str())) p = pe;
    }
    if (p.empty()) p = find_executable("prover9");
    if (p.empty()) {
      fprintf(stderr,
              "proofcheck: prover9 not found.  prover9 is mandatory for "
              "cnf-leaf clausification / provenance validation.  Place it "
              "alongside proofcheck (%s/prover9) or in PATH.\n",
              Exe_dir.empty() ? "<exe-dir>" : Exe_dir.c_str());
      emit_status("%% SZS status Unknown : prover9 backend not found\n");
      return 1;
    }
    Prover9_command = p;
    fprintf(stderr, "Clausifier (prover9): %s\n", p.c_str());
  }

  














  {
    std::string v;
    if (!Exe_dir.empty()) {
      std::string ve = Exe_dir + "/vampire";
      if (is_executable_file(ve.c_str())) v = ve;
    }
    if (v.empty()) v = find_executable("vampire");
    if (v.empty()) v = find_executable("vampire_gnu");
    if (v.empty()) {
      fprintf(stderr,
              "proofcheck: vampire not found.  vampire is mandatory: it's "
              "the backup ATP for cross-checking an inconclusive E "
              "verdict, the backend for TFA (arithmetic) steps E cannot "
              "reason about, and the clausifier for cnf-leaf provenance "
              "validation on Vampire-sourced proofs.  Place it alongside "
              "proofcheck (%s/vampire or %s/vampire_gnu) or in PATH.\n",
              Exe_dir.empty() ? "<exe-dir>" : Exe_dir.c_str(),
              Exe_dir.empty() ? "<exe-dir>" : Exe_dir.c_str());
      emit_status("%% SZS status Unknown : vampire backend not found\n");
      return 1;
    }
    Vampire_command = v;
    fprintf(stderr, "Clausifier (vampire): %s\n", v.c_str());
  }

  


  std::string auto_problem_path;
  if (input_file && !problem_file) {
    FILE *hf = fopen(input_file, "r");
    if (hf) {
      char hline[1024];
      
      for (int hi = 0; hi < 20 && fgets(hline, sizeof(hline), hf); hi++) {
        const char *pp = strstr(hline, "% Proof");
        if (!pp) pp = strstr(hline, "%  Proof");
        if (pp) {
          const char *colon = strchr(pp, ':');
          if (colon) {
            colon++;
            while (*colon == ' ') colon++;
            std::string rel_path(colon);
            
            while (!rel_path.empty() &&
                   (rel_path.back() == '\n' || rel_path.back() == '\r' ||
                    rel_path.back() == ' '))
              rel_path.pop_back();
            if (!rel_path.empty()) {
              
              std::string proof_dir;
              {
                std::string pf(input_file);
                size_t sl = pf.rfind('/');
                if (sl != std::string::npos)
                  proof_dir = pf.substr(0, sl + 1);
              }
              auto_problem_path = proof_dir + rel_path;
              if (access(auto_problem_path.c_str(), R_OK) == 0) {
                problem_file = auto_problem_path.c_str();
                fprintf(stderr, "Auto-detected problem file: %s\n",
                        problem_file);
              } else {
                
                size_t sl = rel_path.rfind('/');
                if (sl != std::string::npos) {
                  auto_problem_path = proof_dir + rel_path.substr(sl + 1);
                  if (access(auto_problem_path.c_str(), R_OK) == 0) {
                    problem_file = auto_problem_path.c_str();
                    fprintf(stderr, "Auto-detected problem file: %s\n",
                            problem_file);
                  }
                }
              }
            }
          }
          break;
        }
      }
      fclose(hf);
    }
  }

  



  if (input_file && !problem_file) {
    FILE *hf = fopen(input_file, "r");
    if (hf) {
      char *hline = NULL;
      size_t hcap = 0;
      ssize_t hlen;
      while ((hlen = getline(&hline, &hcap, hf)) > 0) {
        const char *fp = strstr(hline, "file(");
        if (!fp) continue;
        fp += 5;
        while (*fp == ' ') fp++;
        if (*fp != '\'') continue;
        fp++;
        const char *end = strchr(fp, '\'');
        if (!end || end == fp) continue;
        std::string path(fp, end - fp);
        if (path == "unknown" || path.size() < 2) continue;
        





        std::string cand = path;
        if (access(cand.c_str(), R_OK) != 0 && input_file) {
          std::string pf(input_file);
          size_t sl = pf.find_last_of('/');
          std::string proof_dir = (sl == std::string::npos) ? ""
                                                            : pf.substr(0, sl + 1);
          if (!proof_dir.empty()) {
            std::string c2 = proof_dir + path;
            if (access(c2.c_str(), R_OK) == 0) cand = c2;
            else {
              size_t psl = path.find_last_of('/');
              std::string base = (psl == std::string::npos) ? path
                                                            : path.substr(psl + 1);
              std::string c3 = proof_dir + base;
              if (access(c3.c_str(), R_OK) == 0) cand = c3;
            }
          }
        }
        if (access(cand.c_str(), R_OK) == 0) {
          auto_problem_path = cand;
          problem_file = auto_problem_path.c_str();
          fprintf(stderr, "Auto-detected problem file from file() annotation: %s\n",
                  problem_file);
          break;
        }
      }
      free(hline);
      fclose(hf);
    }
  }

  
  if (!input_file && !model_file) {
    usage();
  }
  if (!problem_file) {
    fprintf(stderr, "proofcheck: problem file required (-p flag or "
            "file() annotations in proof)\n");
    emit_notverified("no problem file: -p not given and no resolvable "
                     "'%% Proof :' header / file() path");
    exit(1);
  }
  if (problem_file && model_file) {
    
  } else if (problem_file && input_file) {
    
  } else {
    usage();
  }

  
  bool use_eval = false;
  Interpretation interp;
  std::vector<FormulaCheck> formulas;
  std::vector<VerifyTask> tasks;

  if (problem_file && model_file) {
    
    use_eval = true;
    std::string tptp_root = find_tptp_root(problem_file);
    if (!tptp_root.empty())
      fprintf(stderr, "TPTP root: %s\n", tptp_root.c_str());

    std::string problem_text = read_tptp_problem(problem_file, tptp_root);
    if (report_unresolved_includes()) return 1;
    std::string raw_model = read_file(model_file);
    std::string model_text = extract_model_text(raw_model);
    if (model_text.empty()) model_text = raw_model;

    fprintf(stderr, "Problem: %s\n", problem_file);
    fprintf(stderr, "Model:   %s\n", model_file);

    if (strict) {
      



      int prob_errors = tptp_validate(problem_text.c_str());
      if (prob_errors > 0)
        fprintf(stderr, "Problem file TPTP syntax: %d warning%s (proceeding)\n",
                prob_errors, prob_errors > 1 ? "s" : "");
      else
        fprintf(stderr, "Problem TPTP syntax: OK\n");
    }

    interp = parse_interpretation(model_text);
    formulas = extract_tptp_formulas(problem_text);
  } else {
    
    std::string text = read_file(input_file);
    Format fmt = detect_format(text);

    



    std::string ladr_prob_override;
    if (fmt == FMT_LADR_PROOF) {
      fprintf(stderr, "Format: LADR proof (Prover9) -- converting to TSTP\n");
      std::vector<LadrProblemFormula> pvec;
      bool ladr_prolog = (text.find("set(prolog_style_variables)") !=
                          std::string::npos);
      if (problem_file) {
        std::string praw = read_file(problem_file);
        if (praw.find("set(prolog_style_variables)") != std::string::npos)
          ladr_prolog = true;
        if (praw.find("formulas(") != std::string::npos) {
          if (!ladr_problem_to_tptp(praw, pvec, ladr_prob_override,
                                    ladr_prolog)) {
            fprintf(stderr, "proofcheck: no formulas found in LADR problem "
                    "file '%s'\n", problem_file);
            emit_notverified("LADR problem file contains no formulas");
            exit(1);
          }
        }
        


      }
      std::string tstp, why;
      if (!ladr_proof_to_tstp_text(text, pvec, ladr_prolog, tstp, why)) {
        fprintf(stderr, "proofcheck: LADR proof not convertible: %s\n",
                why.c_str());
        emit_status("%% SZS status Unknown : LADR proof not convertible: "
                    "%s\n", why.c_str());
        return 1;
      }
      if (getenv("PROOFCHECK_DUMP_LADR")) {
        fprintf(stderr, "--- converted problem ---\n%s"
                "--- converted proof ---\n%s---\n",
                ladr_prob_override.c_str(), tstp.c_str());
      }
      text = tstp;
      fmt = FMT_TSTP_PROOF;
    }

    if (fmt == FMT_UNKNOWN) {
      fprintf(stderr, "proofcheck: cannot detect format of '%s'\n", input_file);
      fprintf(stderr, "Expected TSTP proof, AGMV model, LADR proof, or LADR model.\n");
      



      emit_status("%% SZS status Unknown\n");
      return 1;
    }

    
    if (fmt == FMT_TSTP_PROOF || fmt == FMT_AGMV_MODEL) {
      
      std::string validate_text = text;
      size_t vs = text.find("% SZS output start");
      if (vs != std::string::npos) {
        size_t vnl = text.find('\n', vs);
        size_t ve = text.find("% SZS output end", vnl);
        if (vnl != std::string::npos && ve != std::string::npos)
          validate_text = text.substr(vnl + 1, ve - vnl - 1);
      }
      int hard_errors = 0;
      int syn_errors = tptp_validate(validate_text.c_str(), NULL, 0,
                                     &hard_errors);
      if (syn_errors > 0) {
        fprintf(stderr, "TPTP syntax: %d error%s%s\n",
                syn_errors, syn_errors > 1 ? "s" : "",
                hard_errors > 0 ? " (illegal construct)" : "");
        




        if (hard_errors > 0)
          emit_status("%% SZS status VerifiedBad : malformed proof "
                      "(illegal non-clausal construct in a cnf clause)\n");
        else
          emit_status("%% SZS status Unknown\n");
        return 1;
      }
      fprintf(stderr, "TPTP syntax: OK\n");
    }

    if (fmt == FMT_TSTP_PROOF) {
      fprintf(stderr, "Format: TSTP proof (structural + ATP verification)\n");
      std::vector<std::string> dup_names;
      bool prof_on = (getenv("PROOFCHECK_PROFILE") != NULL);
      long t_pp0 = 0;
      auto pp_now = []() {
        struct timeval tv; gettimeofday(&tv, NULL);
        return (long)tv.tv_sec * 1000000L + tv.tv_usec;
      };
      if (prof_on) t_pp0 = pp_now();
      Proof_symbol_types.clear();
      auto clauses = parse_tstp_proof(text, &dup_names, NULL, &Proof_symbol_types);
      if (report_tstp_parse_error("proof file")) return 1;
      long t_parse_proof_us = prof_on ? (pp_now() - t_pp0) : 0;

      








      {
        ProofSourceDetection psd = detect_proof_source(clauses);
        switch (psd.best) {
          case PSRC_E:       Atp_type = ATP_EPROVER; break;
          case PSRC_VAMPIRE: Atp_type = ATP_VAMPIRE; break;
          case PSRC_PROVER9: Atp_type = ATP_PROVER9; break;
          default: break;  


        }
      }
      



      if (!problem_file) {
        fprintf(stderr, "No problem file found (use -p or include "
                "valid file() annotations)\n");
        emit_status("%% SZS status Unknown\n");
        return 1;
      }
      {
        long t1 = prof_on ? pp_now() : 0;
        std::string ptxt;
        if (!ladr_prob_override.empty()) {
          

          ptxt = ladr_prob_override;
        } else {
          std::string tptp_root = find_tptp_root(problem_file);
          ptxt = read_tptp_problem(problem_file, tptp_root);
          if (report_unresolved_includes()) return 1;
        }
        long t_read_problem_us = prof_on ? (pp_now() - t1) : 0;
        long t2 = prof_on ? pp_now() : 0;
        {
          


          int prob_errors = tptp_validate(ptxt.c_str());
          if (prob_errors > 0)
            fprintf(stderr, "Problem file TPTP syntax: %d warning%s "
                    "(proceeding)\n", prob_errors, prob_errors > 1 ? "s" : "");
        }
        long t_validate_us = prof_on ? (pp_now() - t2) : 0;
        long t3 = prof_on ? pp_now() : 0;
        std::multimap<std::string, ProblemFormula> pformula_alts;
        std::map<std::string, ProblemFormula> pformulas =
            parse_problem_formulas(ptxt, &pformula_alts);
        if (report_tstp_parse_error("problem file")) return 1;
        long t_parse_problem_us = prof_on ? (pp_now() - t3) : 0;
        


        Problem_symbols.clear();
        {
          const std::string &b = ptxt;
          size_t i = 0;
          while (i < b.size()) {
            



            if (b[i] == '%') {
              























              while (i < b.size() && b[i] != '\n') i++;
              if (i < b.size()) i++;
              continue;
            }
            if (b[i] == '/' && i + 1 < b.size() && b[i + 1] == '*') {
              i += 2;
              while (i + 1 < b.size() && !(b[i] == '*' && b[i + 1] == '/')) i++;
              i += 2;
              continue;
            }
            
            if (b[i] == '\'') {
              size_t start = i;
              i++;
              while (i < b.size()) {
                if (b[i] == '\'') {
                  if (i + 1 < b.size() && b[i+1] == '\'') { i += 2; continue; }
                  i++; break;
                }
                i++;
              }
              Problem_symbols.insert(b.substr(start, i - start));
              
              if (i - start >= 2)
                Problem_symbols.insert(b.substr(start + 1, i - start - 2));
              continue;
            }
            























            while (i < b.size() && !isalpha((unsigned char)b[i]) &&
                   b[i] != '_' && b[i] != '$' && b[i] != '\'' &&
                   b[i] != '%' &&
                   !(b[i] == '/' && i + 1 < b.size() && b[i + 1] == '*'))
              i++;
            if (i >= b.size()) break;
            if (b[i] == '\'' || b[i] == '%' ||
                (b[i] == '/' && i + 1 < b.size() && b[i + 1] == '*'))
              continue;  
            size_t start = i;
            while (i < b.size() && (isalnum((unsigned char)b[i]) ||
                                     b[i] == '_' || b[i] == '$')) i++;
            std::string id = b.substr(start, i - start);
            if (id.empty()) continue;
            if (id[0] >= 'A' && id[0] <= 'Z') continue;
            Problem_symbols.insert(id);
          }
        }
        fprintf(stderr, "Problem: %s (%d formulas, %zu symbols)\n",
                problem_file, (int)pformulas.size(), Problem_symbols.size());
        long t4 = prof_on ? pp_now() : 0;
        int rc = verify_tstp_proof(clauses, max_children, timeout_sec,
                                   &pformulas, &dup_names, &pformula_alts);
        if (prof_on) {
          long t_verify_us = pp_now() - t4;
          fprintf(stderr,
                  "PROFILE_SETUP parse_proof=%ldus read_problem=%ldus "
                  "validate=%ldus parse_problem=%ldus verify=%ldus\n",
                  t_parse_proof_us, t_read_problem_us, t_validate_us,
                  t_parse_problem_us, t_verify_us);
        }
        return rc;
      }
    } else if (fmt == FMT_AGMV_MODEL) {
      use_eval = true;
      fprintf(stderr, "Format: AGMV model (direct evaluation)\n");
      auto model = parse_agmv(text);
      interp = parse_interpretation(model.model_text);
      
      for (auto &mc : model.clauses) {
        FormulaCheck fc;
        fc.name = mc.name;
        fc.lang = mc.lang;
        fc.role = mc.role;
        fc.body = extract_body(mc.text);
        if (!fc.body.empty()) formulas.push_back(fc);
      }
    } else if (fmt == FMT_LADR_PROOF) {
      

      emit_status("%% SZS status Unknown : LADR proof reached the format "
                  "dispatch unconverted (internal error)\n");
      return 1;
    } else if (fmt == FMT_LADR_MODEL) {
      use_eval = true;
      fprintf(stderr, "Format: LADR model (direct evaluation)\n");
      
      size_t ip = text.find("interpretation(");
      if (ip != std::string::npos) {
        size_t ds = ip + 15;
        while (ds < text.size() && text[ds] == ' ') ds++;
        size_t de = ds;
        while (de < text.size() && text[de] >= '0' && text[de] <= '9') de++;
        int domain_size = atoi(text.substr(ds, de - ds).c_str());
        size_t mb1 = text.find('[', de);
        if (mb1 == std::string::npos) { fprintf(stderr, "proofcheck: malformed LADR model\n"); emit_notverified("malformed LADR model in -m input"); exit(1); }
        size_t mb2 = text.find(']', mb1);
        if (mb2 == std::string::npos) { fprintf(stderr, "proofcheck: malformed LADR model\n"); emit_notverified("malformed LADR model in -m input"); exit(1); }
        size_t bb1 = text.find('[', mb2);
        if (bb1 == std::string::npos) { fprintf(stderr, "proofcheck: malformed LADR model\n"); emit_notverified("malformed LADR model in -m input"); exit(1); }
        int depth = 0;
        size_t bb2 = bb1;
        for (size_t j = bb1; j < text.size(); j++) {
          if (text[j] == '[') depth++;
          else if (text[j] == ']') { depth--; if (depth == 0) { bb2 = j; break; } }
        }
        std::string interp_body = text.substr(bb1 + 1, bb2 - bb1 - 1);
        std::string model_tptp = ladr_model_to_tptp(interp_body, domain_size);
        interp = parse_interpretation(model_tptp);
      }
      
      size_t mc = text.find("formulas(mace4_clauses).");
      if (mc != std::string::npos) {
        size_t mcnl = text.find('\n', mc);
        size_t mce = text.find("end_of_list.", mcnl);
        if (mcnl != std::string::npos && mce != std::string::npos) {
          std::string clause_section = text.substr(mcnl + 1, mce - mcnl - 1);
          int clause_num = 0;
          std::string current;
          size_t cp = 0;
          while (cp < clause_section.size()) {
            size_t nl = clause_section.find('\n', cp);
            if (nl == std::string::npos) nl = clause_section.size();
            std::string line = clause_section.substr(cp, nl - cp);
            cp = nl + 1;
            strim(line);
            if (line.empty() || line[0] == '%') continue;
            if (!current.empty()) current += " ";
            current += line;
            if (!current.empty() && current.back() == '.') {
              current.pop_back();
              rtrim(current);
              if (!current.empty() && current != "$F") {
                clause_num++;
                FormulaCheck fc;
                fc.name = "clause_" + std::to_string(clause_num);
                fc.lang = "cnf";
                fc.role = "axiom";
                fc.body = ladr_to_tptp_clause(current);
                formulas.push_back(fc);
              }
              current.clear();
            }
          }
        }
      }
    }
  }

  
  if (use_eval) {
    if (formulas.empty()) {
      fprintf(stderr, "proofcheck: no clauses to verify.\n");
      emit_notverified("no clauses to verify in -m model input");
      exit(1);
    }
    int rc = verify_model_direct(interp, formulas);
    fflush(stdout);
    fflush(stderr);

    if ((assurance_level >= 1 && rc != 0) || assurance_level >= 2) {
      
      fprintf(stderr, "\n--- %s: cross-checking with Vampire ---\n",
              assurance_level >= 2 ? "Full assurance" : "High assurance");
      fflush(stderr);
      std::vector<VerifyTask> vamp_tasks;
      if (problem_file && model_file) {
        std::string tptp_root = find_tptp_root(problem_file);
        std::string ptxt = read_tptp_problem(problem_file, tptp_root);
        if (report_unresolved_includes()) return 1;
        std::string raw = read_file(model_file);
        std::string mtxt = extract_model_text(raw);
        if (mtxt.empty()) mtxt = raw;
        vamp_tasks = build_separate_model_tasks(ptxt, mtxt);
      } else if (input_file) {
        std::string text = read_file(input_file);
        Format fmt = detect_format(text);
        if (fmt == FMT_AGMV_MODEL) {
          auto model = parse_agmv(text);
          vamp_tasks = build_model_tasks(model);
        } else if (fmt == FMT_LADR_MODEL) {
          vamp_tasks = build_ladr_model_tasks(text);
        }
      }
      if (vamp_tasks.empty()) {
        fprintf(stderr, "Warning: could not build Vampire tasks for cross-check.\n");
      } else {
        verify_parallel(vamp_tasks, max_children, timeout_sec);
      }
    }
    return rc;
  } else {
    if (tasks.empty()) {
      fprintf(stderr, "proofcheck: no verification tasks found.\n");
      emit_notverified("no verification tasks found in input");
      exit(1);
    }
    VerifyResult r = verify_parallel(tasks, max_children, timeout_sec);
    return r.failed > 0 ? 1 : 0;
  }
}
